(window.GIM_TP=window.GIM_TP||{})["Menachot.1"]={"from":205,"a":[[["מיבעיא לי מאי גברא לשני פרים קא מכוין ועד דממלי להו לא קרבי או דלמא לשני אילים וכבש אחד קמכווין תרי מחד מינא וחד מחד מינא אמרינן או לא מאי תיקו:","\u0001מתני׳\u0002 מתנדבין יין ואין מתנדבין שמן דברי רבי עקיבא רבי טרפון אומר מתנדבין שמן","אמר רבי טרפון מה מצינו ביין שהוא בא חובה ובא נדבה אף שמן שהוא בא חובה בא נדבה אמר לו רבי עקיבא לא אם אמרת ביין שכן קרב עם חובתו בפני עצמו תאמר בשמן שאינו קרב עם חובתו בפני עצמו","אין שנים מתנדבין עשרון אחד אבל מתנדבין עולה ושלמים ועוף אפילו פרידה אחת:","\u0001גמ׳\u0002 אמר רבא מדברי שניהם נלמוד מתנדב אדם מנחת נסכים בכל יום","פשיטא מהו דתימא מנחת נדבה גלי בה רחמנא הני חמשה מנחות אין טפי לא קא משמע לן הני מילי בסתמא אבל היכא דפריש פריש:","אין שנים מתנדבין: מאי טעמא אילימא משום דכתיב (ויקרא ב, א) תקריב עולה נמי הא כתיב (ויקרא א, ב) יקריב","אלא עולה מאי טעמא דכתיב (במדבר כט, לט) לעולותיכם מנחה נמי הא כתיב (במדבר כט, לט) למנחותיכם אלא משום דכתיב בה (ויקרא ב, א) נפש","תניא נמי הכי רבי אומר (ויקרא כב, יח) אשר יקריב קרבנו לכל נדריהם ולכל נדבותם אשר יקריבו לה' הכל באין בשותפות לא סילק הכתוב אלא מנחה שנאמר נפש","אמר ר' יצחק מפני מה נשתנית מנחה שנאמר בה נפש אמר הקדוש ברוך הוא מי דרכו להביא מנחה עני מעלה אני עליו כאילו הקריב נפשו לפני","אמר ר' יצחק מה נשתנית מנחה שנאמר בה חמשה מיני טיגון הללו משל למלך בשר ודם שעשה לו אוהבו סעודה ויודע בו שהוא עני אמר לו עשה לי מן חמשה מיני טיגון כדי שאהנה ממך:","\u0001הדרן עלך פרק המנחות והנסכים\u0002","מתני׳ \u0001הרי\u0002 עלי עשרון יביא אחד עשרונות יביא שנים פירשתי ואיני יודע מה פירשתי יביא ששים עשרון","הרי עלי מנחה יביא איזו שירצה רבי יהודה אומר יביא מנחת הסולת שהיא מיוחדת שבמנחות","מנחה או מין המנחה יביא אחת מנחות או מין מנחות יביא שתים פירשתי ואיני יודע איזה מהן פירשתי יביא חמשתן","פירשתי מנחה של עשרונים ואיני יודע כמה פירשתי יביא ששים עשרון רבי אומר יביא מנחות של עשרונות מאחד ועד ששים:","\u0001גמ׳\u0002 פשיטא עשרונות יביא שתים איצטריכא ליה הא נמי פשיטא מיעוט עשרונות שתים איצטריכא ליה:","פירשתי ואיני יודע מה פירשתי יביא ששים עשרון: מאן תנא","אמר חזקיה דלא כרבי דאי רבי האמר יביא מנחות של עשרונות מאחד ועד ששים","ורבי יוחנן אמר אפילו תימא רבי באומר פירשתי עשרונות אבל לא קבעתים בכלי דמייתי שיתין עשרונות בשיתין מאני:","הרי עלי מנחה יביא איזהו שירצה [וכו']: תנא הואיל ופתח בו הכתוב תחלה","אלא מעתה האומר הרי עלי עולה יביא בן בקר הואיל ופתח בו הכתוב"],[[0,"אחד עשר מיבעיא לי מאי גברא לשני פרים איכוין ועד דממלי להו","לי\"ב לוגין לא קרבי דהא יש קבע לנסכים ולא אמרינן ליקרבו שמנה לוגין לשני אילים ושלשה לוגין לכבש אחד או דלמא למנחה הראויה לשני אילים וכבש איכוין:"],[0,"ה\"ג תרי מחד מינא וחד מחד מינא אמרינן או לא","כלומר מי הוי אורחא לאינדובי או לא:"],[1,"מתני' מתנדבין יין","בלא שמן וסלת ומנסכו לשיתין בפני עצמו ואין מתנדבין שמן בלא סלת ויין:"],[1,"מתנדבין שמן","וקומצו ומקטיר הקומץ ושיריו נאכלין:"],[2,"מה מצינו כו'","דאמרן לעיל אזרח מלמד שמתנדבין נסכין ורבי עקיבא מוקי לה ביין (כדחזינן) כדקתני מתנדבין יין ולא שמן:"],[2,"אף שמן שהוא בא חובה","במנחת נסכים בא נדבה בפני עצמה:"],[2,"עם חובתו בפני עצמו","אע\"פ שהוא בא חובה עם המנחה אינו מעורב במנחה תאמר בשמן כו' וכיון דלא אשכחן ליה דליתי בכלי בפני עצמו השתא נמי לא לייתי:"],[3,"אפילו פרידה","אפי' גוזל א' מתנדבין:"],[4,"גמ' מדברי שניהם נלמד מתנדב אדם מנחת נסכים","סלת שמן ויין בלא קרבן בכל יום דעד כאן לא פליגי אלא בפני עצמו אבל במעורב עם המנחה לא פליגי:"],[5,"חמשה מנחות","סלת ומחבת ומרחשת וחלות ורקיקין אבל רבוכה לא חשיב דאינה באה נדבה אלא בתודה עם הזבח ולאו מנחה היא:"],[5,"קמ\"ל","הא דהני חשיב ותו לא היכא דאמר מנחה סתם יביא אחת מחמש הללו:"],[5,"אבל היכא דפריש","לנסכים פריש:"],[6,"מאי טעמא","אין שנים מתנדבין עשרון:"],[6,"תקריב","לשון יחיד:"],[7,"עולותיכם","לשון רבים:"],[9,"עני","דרכו להביא מנחה שאין לו בהמות:"],[10,"חמשה מיני טיגון","סלת מחבת ומרחשת וחלות ורקיקין דמנחת מאפה כל מידי דאית ביה שמן קרי טיגון:"],[10,"שאהנה ממך","כלומר שתקובל לפני בהן:"],[12,"מתני' הרי עלי עשרון: פירשתי","כמה עשרונים אביא:"],[12,"ואיני יודע מה פירשתי יביא ששים עשרונים","דאי בציר מהכי נדר לא איכפת ליה דמתני ואמר כמה שנדרתי יהיו לנדרי והשאר יהא נדבה ובטפי ליכא לספוקי דאין מנחה יחידית יתירה על ששים עשרונים:"],[13,"הרי עלי מנחה","סתם:"],[13,"יביא איזו שירצה","מחמשה מנחות:"],[13,"מיוחדות","מפרש בגמרא:"],[14,"מין המנחה","כלומר הרי עלי מנחה או שאמר הרי עלי מין המנחה יביא אחת:"],[14,"מנחות","עלי או שאמר מין מנחות עלי יביא שתי מנחות ממין אחד:"],[14,"פירשתי","אחת מן המנחות שכתובים בפרשה ואיני יודע אי זה מהן פירשתי כו':"],[15,"פירשתי מנחה","בכלי אחד של עשרונים:"],[15,"ואיני יודע כמה","עשרונים קבעתי בה:"],[15,"יביא ששים עשרון","דבטפי מהכי ליכא לספוקי ואי בציר נדר לא איכפת לן דמתני ואמר כמה שפירשתי יהא לנדרי והשאר יהא לנדבה:"],[15,"רבי אומר","כיון דאמר מנחה משמע חדא אלמא בכלי אחד קבעה ואם יביא ששים בכלי אחד שמא בציר מהכי נדר והויא מנחה יתירה ואית ליה לרבי קביעותא דמנא מילתא הלכך יביא ששים מנחות מאחד ועד ששים חדא של עשרון וחדא של שתים וחדא של שלש וחדא של ארבע וכן עד ששים דודאי חדא מינייהו נדר ואינך נדבה:"],[19,"גמ' אבל לא קבעתים בכלי אחד","הלכך יביא ששים עשרונות בששים כלים כל אחד ואחד בפני עצמו והא דקאמר יביא מנחות של עשרונות מאחד ועד ששים היינו היכא דקבעה בכלי אחד דלא מצי לאיתויי בכלי אחד לא בציר מהכי ולא טפי מהכי הלכך יביא מנחות של עשרונים מאחד ועד ששים דודאי חדא מינייהו נדר:"],[20,"תנא","מה טעם יביא מנחת סלת לפי שפתח בה הכתוב תחלה:"]],[[9,"","מה נשתנית שנאמר בה נפש. דאי משום דאין באה בשותפות הוה ליה למיכתב איש או לשון אחר דמשמע יחיד דוקא:"],[10,"","חמשה מיני טיגון. לא היה מטגן מנחת סולת מאפה תנור אלא מנחת מחבת ומרחשת לחודייהו אלא קורא טיגון מה שיש בכולו שמן:"],[13,"","מתני' הרי עלי מנחה יביא איזו שירצה. פירוש מחמשת מנחות אבל במנחת נסכים לא איכוין אע\"ג דמתנדב אדם מנחת נסכים בכל יום דסתמא דעתו אמנחות המפורשות ורגילות לבא בפני עצמן ולא בגלל זבח:"],[14,"","מנחה מין המנחה. פירוש או אמר מין המנחה:"]]],[["תחלה","מן הצאן יביא כבש הואיל ופתח בו הכתוב תחלה","מן העוף יביא תורים הואיל ופתח בו הכתוב תחלה","אלמה תנן הרי עלי עולה יביא כבש רבי אלעזר בן עזריה אומר תור או בן יונה ולא פליג רבי יהודה","אלא מאי מיוחדת שבמנחות דלית ליה שם לווי","והא תנא הואיל ופתח בו הכתוב תחלה קאמר הכי קאמר איזהו מנחה מיוחדת שבמנחות דלית ליה שם לווי זו שפתח בו הכתוב תחלה","פשיטא מנחת הסולת קאמר סימנא בעלמא:","מנחה מין המנחה [וכו']: בעי רב פפא מיני מנחה מהו","כיון דאמר מיני תרתי קאמר ומאי מנחה דכולה מנחות נמי מנחה מיקריין דכתיב (ויקרא ז, א) וזאת תורת המנחה","או דלמא כיון דאמר מנחה חדא מנחה קאמר ומאי מיני מנחה הכי קאמר ממיני מנחה חדא מנחה עלי","תא שמע מנחה מין מנחה יביא אחת הא מיני מנחה שתים","אימא סיפא מנחות מין מנחות יביא שתים הא מיני מנחה חדא אלא מהא ליכא למשמע מינה:","תא שמע מין מנחות עלי יביא שתי מנחות ממין אחד הא ממיני מנחה חדא","דלמא הא מיני מנחה מביא שתי מנחות משני מינין","והא לא תני הכי מין מנחות עלי מביא שתי מנחות ממין אחד מיני מנחות עלי מביא שתי מנחות משני מינין הא מיני מנחה חדא","דלמא הא מני רבי שמעון היא דאמר מחצה חלות ומחצה רקיקין יביא ומאי מיני מנחה מנחה דאית בה תרי מיני","אבל רבנן דאמרי מחצה חלות ומחצה רקיקין לא יביא מביא שתי מנחות משני מינין:","פירשתי ואיני יודע מה פירשתי יביא חמשתן: מאן תנא","אמר רבי ירמיה דלא כרבי שמעון דאי רבי שמעון כיון דאמר מחצה חלות ומחצה רקיקין יביא","אי נמי סבר לה כר' יהודה דאמר כל המנחות באות עשר איכא לספוקה בארבע עשרה מנחות","אביי אמר אפילו תימא רבי שמעון שמעינן ליה לרבי שמעון דאמר מייתי ומתני","דתניא רבי שמעון אומר למחרת מביא אשמו ולוגו"],[[1,"מן הצאן יביא כבש","אמר הרי עלי עולה מן הצאן יביא כבש ולא עז הואיל ופתח בו וכו':"],[4,"דלית ליה שם לווי","שנקראת מנחה סתם דשאר מנחות יש להם שם לווי מנחת מחבת ומנחת מרחשת ומנחת מאפה:"],[5,"איזו היא מנחה דקרי לה ר' יהודה מיוחדת","משום דלית ליה שם לווי זה שפתח בה הכתוב תחלה והיינו מנחת סלת:"],[6,"פשיטא דמנחת סלת קאמר","ר' יהודה דהא בהדיא קתני לה:"],[6,"סימנא בעלמא","לגירסא שלא תטעה ותשכח איזו מנחה קאמר ר' יהודה דיביא סימן זה יהא בידך זו שפתח בה הכתוב תחלה:"],[8,"וזאת תורת המנחה","בצו את אהרן ואכולהו מנחות קאי:"],[10,"ת\"ש","ממתני':"],[10,"מנחה מין המנחה","פירשתי לעיל:"],[10,"יביא אחת","משום דמין חד משמע ומנחה נמי חדא משמע:"],[10,"הא מיני מנחה שתים","יביא שתים:"],[12,"ממין אחד","דמוקים לתרוייהו [לישני]:"],[13,"דלמא הא מיני מנחה יביא שתי מנחות משתי מינין","דמיני (מנחה) משמע תרין [ומנחה נמי משמע תרין] כדאמר לעיל וזאת תורת המנחה:"],[15,"ודילמא","הא דדייקינן מינה הא מיני מנחה חדא ר' שמעון היא דלדידיה איכא לקיומי תרוייהו [לישני] שני מינין במנחה אחת אבל לרבנן דלית להו מנחה משני מינים לעולם חדא מנחה ממין אחד (לא) מייתי:"],[17,"מאן תנא","דלא מספקא ליה אלא בחמשה מנחות:"],[18,"כיון דאמר מחצה חלות ומחצה רקיקין יביא","ולאו דוקא קאמר דה\"ה לתשע חלות וחד רקיק או לתשעה רקיקין וחדא חלה:"],[19,"אי נמי סבר לה כרבי יהודה דאמר","בפרק ואלו מנחות (לעיל מנחות עו.) כל המנחות באות עשר עשר:"],[19,"איכא לספוקי להאי בארבע עשרה מנחות","סלת ומחבת ומרחשת הרי ג' ומנחת מאפה איכא אחד עשר ספיקות דלמא כולה חלות נדר ושמא תשעה חלות וחד רקיק ושמא שמנה חלות ושני רקיקין וכן גרועי לחלות ואסופי לרקיקין עד שמא כולה רקיקין [הוי י\"א]:"],[20,"מייתי","שתי מנחות חדא של עשר חלות וחדא של עשר רקיקין ואומר אם כולה חלות או כולה רקיקין נדרתי אותה שנדרתי תהא לנדרי והאחרת תהא נדבה ואם מחצה של חלות ורקיקין נדרתי יצטרפו חלות מזו לפי מה שנדרתי ורקיקין מזו לפי מה שנדרתי לנדרי והאחרת תהא נדבה:"],[21,"למחרת מביא אשמו ולוגו עמו","בתוספת' דנזירות קתני לה מי שהיה ספק נזיר טמא וספק טהור ספק מצורע מוחלט טמא ספק טהור אוכל בקדשים אחר ס' יום כו' רבי שמעון אומר למחרת של יום ששים מביא אשמו כו':"]],[[6,"","סימנא בעלמא. לגירסא שלא תטעה ושלא תשכח באיזה מנחה א\"ר יהודה כי על ידי טעם זה אתו לאדכורי גמרא:"],[21,"","למחרת מביא אשמו ולוגו. פירש בקונטרס למחרת יום ששים ובזבחים (דף עו.) פירש למחרת יום שמיני והכל אחד דאספק נזיר טמא ואספק מצורע טמא קאי כדמוכח בתוספתא דנזיר פרק בתרא והכי איתא התם ספק נזיר טמא וספק נזיר טהור אבל נזיר ודאי היה ספק מצורע טמא פי' מוחלט ספק מצורע טהור פי' שטהור כבר אבל מצורע ודאי היה פי' בחד גברא איירי שיש בו ספיקות הללו אוכל בקדשים לאחר ששים יום ושותה יין ומיטמא למתים לאחר ק\"כ יום כיצד אמרו לו נזיר טמא אתה [ואין נזיר טמא מגלח אלא עד שבעה] צא ומנה שבעה הזה ושנה וגלח והבא קרבן מנה שבעה ומבקש לגלח אמרו לו נזיר טהור אתה ואין טהור מגלח פחות מל' יום צא ומנה כ\"ג להשלים לז' מנה ל' ומבקש לגלח א\"ל נזיר טהור אתה ואין טהור מגלח אלא על הדמים פירוש שלש בהמות חייב להביא חטאת עולה ושלמים ועל אחד מהם יכול לגלח וחטאת בהמה אינה באה על הספק ושלמי נזיר נמי טעון תנופה וזה אין יכול להניף מפני שהוא ספק מצורע טמא אבל עולה יכול להביא על תנאי והיינו דקתני כיצד הוא עושה מביא עולת בהמה ומתנה עליה ואומר אם טהור אני הרי זו חובה ואם לאו הרי זו נדבה כיצד הוא עושה להחמיר עליו מביא פיילי של חרס חדשה ונותנין לתוכה רביעית מים חיים ומביא שני ציפורי דרור פירוש כדין כל מצורעין ביום תגלחתם וחטאת העוף פי' כדין נזיר טמא דשמא טמא הוא ותגלחת זו של טומאה ואינו מתחיל נזירות טהרה עד שיביא חטאתו של טומאה שחטאתו מעכבתו מלמנות נזירות טהרה אבל אשמו אינו מעכבו ומשיגלח תגלחת טומאה הוא אסור לגלח עד שימנה נזירות טהרה ולהכי צריך להביא חטאת נזירות טומאה למנות נזירות טהרה ולגלח בסופה לטהרת צרעתו ואשם ישהה עד תגלחת הטומאה שיעשה אחרי טהרתו בודאי מן הצרעת שאותה תעלה לו ודאי לטומאת נזרו כמו שמפרש בסוף הברייתא דימי צרעתו אין עולין לו לימי נזרו ותגלחת צרעתו אינה עולה לתגלחת נזרו כדאמר בפרק מי שאמר הריני נזיר מגלח (נזיר יז:) ובפרק שני נזירים (שם סט:) ומה שמביא חטאתו ביום תגלחתו היינו כרבי עקיבא דאמר במסכת נזיר (דף מד:) אם גילח בשמיני מביא קרבנותיו בו ביום והכי נמי הוי כגילח בשמיני שהרי שיהה תגלחתו ומתנה על חטאתו ואומר אם טמא אני חטאת מחובתי ועולה נדבה פי' עולה שאמרנו למעלה ואם טהור אני עולה מחובתי וחטאת העוף ספק מגלח ראשו וזקנו וגבות עיניו כדרך שהמצורעים מגלחין ומביא עולת בהמה [ומתנה עליה כו' וסופר שלשים יום ומביא עולת בהמה כו'] שהרי ספק נזירות טהרה הוא מונה ואינו יכול לגלח תגלחת שניה לצרעתו עד שיזרוק עליו אחד מן הדמים ומביא עולה וחטאת ושלמים (ודאי עולת בהמה) וישהה עד סוף נזירות טהרה שאחר טהרת צרעתו שעולה בודאי ואומר אם טמא אני פירוש אם טמא הייתי בתגלחת ראשונה העולה ראשונה נדבה היתה וזו תהיה חובה וחטאת העוף שהבאתי בתגלחת ראשונה מחובתי ואם טהור אני עולה ראשונה חובה וזו נדבה שתגלחת זו של עכשיו אינה כלום וחטאת העוף ספק ומגלח ראשו וזקנו וגבות עיניו כדרך מצורעים ותגלחת זו היתה ראויה לעשות בסוף ז' ימי ספירה תגלחתו ראשונה אבל לא היה יכול משום דגילוח ספק מצורע אינו דוחה איסור גילוח דנזיר רבי שמעון אומר למחרת מביא אשמו ולוגו עמו בידו כדין מצורע בשמיני שלו והוא יום אחד וששים ומתנה עליו לפי שהוא ספק מצורע וחטאת מצורע שמעכבת טהרתו אינו יכול להביא מבהמה שאין חטאת בהמה באה על הספק לפיכך יביא חטאת העוף ואם הוא עשיר יכתוב נכסיו לאחר ויהא עני ויביא קרבן עני דהיינו עוף ור\"ש לטעמיה דאמר במסכת ערכין (דף יז:) אפי' היה עשיר בשעה שהביא ציפוריו או בשעת הבאת אשם והעני הכל הולך אחר החטאת ואפילו לתנאי דפליגי עליה איכא לאוקומה להא דהכא ולפרושי יכתוב נכסיו לאחר מעיקרו ומתנה על חטאת העוף ואומר אם טמא הוא פירוש אם מצורע הוא הרי זו חובתו ואם לאו הרי זו ספיקו ואוכל בקדשים מיד אבל לשתות יין וליטמא למתים אינו יכול שאין ימי נזרו עולין לו לימי צרעתו כיצד יעשה פירוש לדברי בן זומא שאין מצריך לבקש אחד מן השוק לידור כנגדו בנזיר כמו שמצריך רבי יהושע בפרק שני נזירין (נזיר נט:) סופר שלשים ומביא עולת בהמה ומגלח פי' ספק תגלחת טומאה וספק תגלחת טהרה דשמא מצורע היה ונזיר טמא ולא עלו לו אחת מתגלחותיו לנזירותיו רק מצרעתו שאין ימי נזרו עולין מתוך ימי צרעתו ולסוף שבעה אחר ימי טהרת צרעתו אינו יכול לגלח דשמא נזיר טהור הוא אבל הזאה לא בעי שכבר הזה ושנה ואפילו לסוף ל' אינו יכול לגלח עד שיזרוק עליו אחד מן הדמים ומביא חטאת העוף משום ספק תגלחת טומאה שאינו יכול להתחיל מנין נזירות טהרה עד שיביא חטאתו כדפרישית ומתנה עליו כתנאי שלמעלה בתגלחת ראשונה והוא הדין שיש להתנות שאם אינו נזיר עכשיו כלל שכלתה נזירותיו מתגלחת שלמעלה העולה נדבה וחטאת העוף ספיקו אך התנא לא חש לפרש כל זה וסופר שלשים יום ומביא קרבנותיו שלמים ודאי ועולת בהמה ספק ומתנה עליה ואומר אם טמא הייתי בתגלחת שלישית העולה ראשונה נדבה וזו חובה וחטאת העוף מחובתי ואם טהור אני העולה ראשונה חובה וזו נדבה וחטאת העוף ספק והוא הדין נמי דמתנה אם כלתה נזירות מתגלחת שניה שתיהן עולת נדבה וחטאת העוף ספק אך לא חשש לפרש כך ושותה יין ומיטמא למתים תימה למה לא הזכיר בקרבנות תגלחת רביעית זו חטאת [בהמה] שהרי ודאי נזיר היה ועדיין לא הביא חטאת הבהמה בשום פעם ואם באנו לפרש רישא דברייתא ספק נזיר וספק אינו נזיר כלל עכשיו (אבל נזיר ודאי היה) ולכך לא יביא חטאת בהמה שהרי אינה באה על הספק לא משתמע הכי דא\"כ הוה ליה לפרושי בהדיא ועוד א\"כ בשלמים הוה ליה למיתני תנאי או למיהוי עולת נדבה או שלמי נזיר לענין [המורם מהם] דבהאי חזה ושוק ובהאי זרוע בשילה במה דברים אמורים בזמן שנדר שלשים אבל נדר שנים עשר חדש אוכל בקדשים לאחר שתי שנים ושותה יין ומיטמא למתים לאחר ארבעה שנים באותו ענין ובאותה שיטה שאמרנו מגלח לסוף שנה באותה של סוף שלשים ובאותו תנאי ולסוף שתי שנים בשניה ולבסוף ג' שנים בשלישית ולבסוף ארבעה שנים ברביעית טמא בספק ומוחלט בודאי אוכל בקדשים לאחר שמונה ימים דתגלחת מצורע ודאי דוחה איסור גילוח דנזיר ומיד כשיבא לפנינו מגלח ראשונה ובשביעי תגלחת שניה ובשמיני מכניס ידיו לבהונות ושותה יין ומיטמא למתים לאחר ל\"ז כך כתוב בתוספתא ונראה דגרסינן ששים ושבעה לפי שיטה שפירשנו טמא בודאי ומוחלט בספק אוכל בקדשים לאחר שלשים ושבעה יום ושותה ביין ומיטמא למתים לאחר ע\"ד יום טמא בודאי ומוחלט בודאי אוכל בקדשים לאחר שמונה ימים ושותה יין ומטמא למתים לאחר ארבעה וארבעים יום:"]]],[["עמו ואומר אם מצורע הוא זהו אשמו וזה לוגו ואם לאו אשם זה יהא שלמי נדבה","ואותו אשם טעון שחיטה בצפון ומתן בהונות וסמיכה ונסכים ותנופת חזה ושוק ונאכל לזכרי כהונה ליום ולילה","ואף על גב דקא מפריק מר בשחיטת קדשים","אימר דאמר רבי שמעון מייתי ומתני לכתחילה לתקוני גברא אבל בעלמא דיעבד אין לכתחילה לא","הני מילי גבי שלמים דקא ממעט באכילתן דהוו להו קדשים לבית הפסול אבל מנחות אפילו לכתחילה","אמר ליה רב פפא לאביי רבי שמעון דאמר מחצה חלות ומחצה רקיקין יביא הא קא מייתי עשרון אחד משני עשרון ולוג אחד משני לוגין","שמעינן ליה לר' שמעון דאמר אם הביא עשרון אחד משני עשרונות ולוג אחד משני לוגין יצא","ומיקמץ היכי קמץ דמתני ואמר אי חלות לחודייהו ורקיקין לחודייהו אמרי דקא קמיצנא מחלות ליהוי אחלות דקא קמיצנא מרקיקין ליהוי ארקיקין אי מחצה רקיקין ומחצה חלות אמרי דקא קמיצנא מחלות ליהוי אמחצה חלות ומחצה רקיקין ודקא קמיצנא מרקיקין ליהוו אמחצה רקיקין ומחצה חלות","והא בעי מיקמץ חד קומץ מחלות"],[[1,"ושחיטתו בצפון","כשאר אשמות:"],[1,"ומתן בהונות","כדין אשם מצורע:"],[1,"וסמיכה ונסכים ותנופת חזה ושוק","כחומר שלמים:"],[1,"ונאכל לזכרי כהונה ליום ולילה","שמא אשם הוא:"],[2,"ואע\"ג דאמר מר","בשחיטת קדשים בפרק כל הזבחים שנתערבו בחטאות המתות (דף עו:):"],[3,"אימר דאמר ר\"ש מייתי ומתני לכתחילה לתקוני גברא","כגון האי דבלאו הכי אסור למיכל בקדשים דשמא מצורע הוא:"],[3,"אבל בעלמא","כגון התם בזבחים דמיירי באשם שנתערב בשלמים דקאמר ר\"ש התם כולן יאכלו כחומר שבהן שיהו כולן נאכלין ליום ולילה כאשם וכולן טעונים סמיכה ונסכים דיעבד אין לכתחילה לא:"],[4,"דקא ממעט באכילתן","דשמא שלמים הן וזמן אכילתן שני ימים ולילה אחד וכיון דאשם אינו נאכל אלא ליום ולילה והנותר שורף נמצא מביא קדשים לבית הפסול שלא כדין אבל מנחות הללו זמן אכילתן שוה אפילו לכתחילה נמי:"],[5,"ולרבי שמעון דאמר מחצה חלות כו'","ומוקמא מתניתין אליביה וכגון דמייתי ומתני שיצטרפו חלות מעשרון זה לפי מה שנדר ורקיקין מעשרון זה לפי מה שנדר:"],[5,"הא קא מייתי","השתא עשרון מזה קצת ומזה קצת וקא מערב שתי מנחות בהדי הדדי ואיהו לא נדר אלא חדא מנחה לאיתויי חד עשרון וחד לוג ומיפלגיה לחלות ורקיקים:"],[6,"שמעינן ליה לר\"ש","דאמר המביא מנחה והביא שני עשרונים ושני לוגין ואמר חציו של זה וחציו של זה לחובתי והשאר נדבה יצא ולא איתפריש לן היכא:"],[7,"ומיקמץ היכי קמץ","לאותה מנחה שהוא מצטרף שתי מנחות למנחה אחת:"],[8,"והא בעי מיקמיץ כו'","דאי חדא מנחה של חלות ורקיקין אמר הוי בעי איתויי חלות ורקיקין ולפותתן בכלי אחד ולקמוץ משניהם קומץ אחד:"]],[[0,"","אשם זה יהא שלמי נדבה. וא\"ת והא אמרינן בפרק איזהו מקומן (זבחים דף מז:) דאשם מצורע שני כהנים מקבלין את הדם אחד ביד ואחד בכלי ושלמים אמרינן דצריך שיקבל כל דמו של פר ויש לומר דתקוני גברא שאני כדאמרינן בפרק התערובות (זבחים דף עו:):"],[1,"","וסמיכה. למ\"ד אשם מצורע לאו דאורייתא הוי באקפויי ידיו ואע\"ג דשלמים בעו סמיכה גמורה ואשכחן בפסחים בפרק האשה (דף פט:) גבי חמשה שנתערבו עורות פסחיהן דנמנעין מלעשות פסח שני מחמת סמיכה משום תקוני גברא התירו ולמ\"ד דאורייתא הזכיר בחנם סמיכה וכן נסכים דבין שלמים בין אשם מצורע טעונין סמיכה ונסכים ומיהו נסכים מצינו למימר דנקט משום שאר אשמות דלא בעו נסכים:"],[1,"","ותנופת חזה ושוק. תימה דלא תני תנופה מחיים דבעי אשם מצורע כדתנן בפרק כל המנחות באות מצה (לעיל מנחות סא.):"],[1,"","ונאכל ליום ולילה. ובתודה דאין נאכלת אלא ליום ולילה אין יכול להתנות משום דבעיא לחם ובלחם אי אפשר לעשות תקנה כדמוכח בפרק התודה (לעיל מנחות פ.):"],[6,"","שמעינן ליה לרבי שמעון דאמר אם הביא עשרון אחד משני עשרונות ולוג אחד משני לוגין יצא. פי' בקונטרס לא איתפריש ויש לדקדק מדקסבר מדת יבש לא נתקדשה דמכשר שתי הלחם ולחם הפנים אבית פאגי שמעת מינה דלא חייש בעשרון משתי עשרונות ומיהו לוג אחד מב' לוגין לא שמעינן מינה דכולהו מודו במדת הלח דנתקדשה:"]]],[["ומרקיקין וקא קמיץ מחלות ארקיקין ומרקיקין אחלות","שמעינן ליה לרבי שמעון דאמר אם קמץ ועלה בידו מאחד על שניהם יצא","והא איכא מותר שמן דאי מחצה חלות ומחצה רקיקין אמר מותר השמן מחזירו לחלות אי כולהו רקיקין אמר מותר השמן נאכל לכהנים","כרבי שמעון בן יהודה דתניא רבי שמעון בן יהודה אומר משום ר' שמעון מושחן כמין כי ומותר השמן נאכל לכהנים","אמר ליה רב כהנא לרב אשי והא איכא לספוקה במנחת נסכים דאמר רבא מתנדב אדם מנחת נסכים בכל יום","כי קא מסתפקא ליה (סימן יחי\"ד בגל\"ל לבונ\"ה בלו\"ג מקמצ\"ה)","באה בגלל יחיד באה בגלל ציבור לא מסתפקא ליה","כי קא מסתפקא ליה באה בגלל עצמה באה בגלל זבח לא מסתפקא ליה","כי קא מסתפקא ליה טעונה לבונה שאינה טעונה לבונה לא מסתפקא ליה","כי קא מסתפקא ליה באה בלוג באה בשלשה לוגין לא מסתפקא ליה","כי קא מסתפקא ליה טעונה קמיצה שאינה טעונה קמיצה לא קא מסתפקא ליה:","פירשתי מנחה של עשרונים:","תנו רבנן פירשתי מנחה וקבעתי בכלי אחד של עשרונים ואיני יודע מה פירשתי יביא מנחה של ששים עשרונים דברי חכמים רבי אומר יביא מנחות של עשרונים מאחד ועד ששים שהן אלף ושמונה מאות ושלשים","פירשתי ואיני יודע מה פירשתי ואי זו מהן פירשתי ואיני יודע כמה פירשתי יביא חמש מנחות של ששים ששים עשרונים שהן שלש מאות דברי חכמים רבי אומר יביא חמש מנחות של ששים עשרונים מאחד ועד ששים שהן תשעה אלפים ומאה וחמשים","במאי קא מיפלגי אמר רב חסדא במותר להכניס חולין לעזרה קא מיפלגי רבי סבר אסור להכניס חולין לעזרה ורבנן סברי מותר להכניס חולין לעזרה","רבא אמר דכולי עלמא אסור להכניס חולין לעזרה והכא במותר לערב חובה בנדבה קא מיפלגי","רבנן סברי מותר לערב חובה בנדבה ורבי סבר אסור לערב חובה בנדבה","אמר ליה אביי לרבא לרבנן דאמרי מותר לערב חובה בנדבה הא בעינן שני קמצים דקמיץ והדר קמיץ","והא קא קמיץ מחובה אנדבה ומנדבה אחובה","דתלי ליה בדעת כהן דאמר כל היכא דמטיא ידא דכהן השתא חובה ולבסוף נדבה","ואקטורי היכי מקטר ליקטר נדבה ברישא דחובה היכי מקטר לה דלמא כולה חובה היא וחסרו להו שירים","ואמר מר שירים שחסרו בין קמיצה להקטרה אין מקטיר קומץ עליהן","ליקטר חובה ברישא דנדבה היכי מקטר לה"],[[1,"שמעינן ליה לר\"ש","בפ' כל המנחות באות מצה (לעיל מנחות סג:):"],[2,"מותר השמן","אמרי' בפ' ואלו מנחות (לעיל מנחות עה.) מנחה הבאה מחצה חלות ומחצה רקיקין מביא לוג שמן וחוצהו לחלות ורקיקין וחלות בוללן ומושח הרקיקין על פני כולן ושאר השמן מחזירו לחלות וגבי כולה רקיקין תניא לעיל מההיא מושחן כמין כי ושאר השמן נאכל לכהנים:"],[3,"רבי שמעון בן יהודה","גבי מחצה חלות ומחצה רקיקין קאי:"],[3,"מותר השמן נאכל לכהנים","כדין רקיקין הבאים בפני עצמן הלכך ממה נפשך מותר של רקיקין נאכל לכהנים:"],[5,"כי קא מספקא ליה","לנדר ממנחת יחיד שאינה באה בצבור דהיינו הנך חמש מנחות הנדבה דאינן באות בצבור כדאמר לעיל (מנחות דף קד:) אין שנים מתנדבים עשרון אחד שהרי כתיב בה נפש אבל מנחת נסכים הבאה בצבור לא מספקא ליה דודאי ידע שלא נדרה:"],[12,"של עשרוני' מאחד ועד ששים","שיביא ששים מנחות בששים כלים בחד כלי חד עשרון ובאידך שנים ובאידך שלשה ובאידך [ארבעה וכן עד] ששים:"],[12,"שהם אלף ושמנה מאות ושלשים עשרונות","ובכל כלי יאמר אם כזו נדרתי זו לנדרי ואם לאו תהא נדבה דממה נפשך חדא מינייהו נדר:"],[13,"פירשתי","עשרונות ופירשתי מאיזה מנחה מן החמש המנחות ואיני יודע מאיזה מנחה פירשתי וכמה עשרונים פירשתי בה יביא חמש מנחות של ששים עשרונות:"],[14,"במותר להכניס חולין לעזרה","ודכולי עלמא אסור לערב חובה בנדבה:"],[14,"ורבי סבר אסור להכניס חולין לעזרה","הלכך לא מצי איתויי בכלי אחד ומתנה אבל יביא ששים מנחות מאחד ועד ששים בששים כלים ויאמר אותם שנדרתי יהו לחובתי והשאר נדבה ואי קשיא לייתי ששים עשרונות בששים כלים ויאמר לפי חשבון שנדרתי יהא לנדרי והשאר נדבה הא לא קשיא דקביעות המנחה מילתא היא ולא מצי לאיתויי בכלי אחד פחות ממה שקבע בו:"],[14,"רבנן סברי מותר להכניס חולין לעזרה","הלכך יביא ששים עשרון בכלי אחד ויתנה אם כולן נדרתי כולן לחובתי ואם לאו מה שנדרתי יהא לחובתי והשאר חולין אבל השאר לנדבה לא מצי לאיתויי דאסור לערב חובה בנדבה ואי קשיא הכא נמי היכי קריב קומץ הא הוי קצת מן הקומץ חולין ועוד מנחה היכי מישתרי והא לא איקמצ' קומץ שלם דקצת מן הקומץ הוי חולין תריץ כדתרצינן בהקומץ רבה (לעיל מנחות כד:) קומץ בדעתא דכהן תליא מילתא וכהן דעתו אקודש ולא אחולין:"],[15,"מותר לערב חובה בנדבה","הלכך מייתי ס' עשרונות ויאמר כפי מה שנדרתי יהו לחובתי והשאר לנדבה:"],[17,"שני קמצים","חד לחובה וחד לנדבה:"],[17,"ומשני דקמיץ","שני קמצים:"],[19,"כל היכא דמטי ידיה דכהן השתא","בקומץ ראשון יהא חובה וכל היכא דמטו ידיה בקומץ אחרון תהא נדבה:"]],[[3,"","כרבי שמעון בן יהודה. ואם תאמר מאי סלקא דעתך דמקשה דקאמרינן דאי מחצה חלות ומחצה רקיקין מותר השמן מחזירו לחלות הא לא אשכחן בפ' ואלו מנחות (לעיל מנחות עה.) רבי שמעון דאית ליה האי סברא ומנא ידע בכולה רקיקין דשאר השמן נאכל לכהנים וי\"ל משום דרבנן דפליגי ארבי שמעון בן יהודה התם סבירא להו במותר השמן מחזירו לחלות ואליבא דרבי שמעון קאמרי דהא קתני מנחה הבאה מחצה חלות ומחצה רקיקים ומאן שמעת ליה דאית ליה האי סברא רבי שמעון:"],[12,"","שהן אלף ושמונה מאות ושלשים. כיצד קח בידך מאחד ועד ששים וצרף תחילתן לסופן עד האמצע כגון אחד וששים הם ס\"א שנים ונ\"ט הם ס\"א ושלש ונ\"ח הם ס\"א כן תמנה עד שלשים דשלשים ושלשים ואחד נמי הם ס\"א ויעלה לך שלשים פעמים ס\"א וכן נוכל למנות פרים דחג דעולין לשבעים כיצד ז' וי\"ג הם עשרים וכן ח' וי\"ב הם עשרים וכן ט' וי\"א הם כ' וי' הרי שבעים:"],[14,"","במותר להכניס חולין לעזרה קמיפלגי. ולא מיתוקמא אלא כרבנן דאמרי למנחה של ששים עשרון ששים לוגין דאי כרבי אליעזר בן יעקב דאמר אין לה אלא לוגה היכי מיתכשרה כיון דאיערב חולין בהדה הא אינה ראויה לבללן משום דהוה ליה חיסר שמנה:"],[15,"","רבה אמר דכולי עלמא וכו'. רבה גרסינן אף על פי שהוא אחר רב חסדא דרבא משני לקמן שינויא אחרינא:"],[19,"","דתלי לה בדעת כהן. ואף על גב דבהקומץ רבה (לעיל מנחות דף כד:) לית ליה לאביי בדעתא דכהן תליא מילתא הכא מודה:"]]],[["ודלמא כולה חובה היא וכל שהוא ממנו לאישים הרי הוא בבל תקטירו","אמר ר' יהודה בריה דרבי שמעון בן פזי דמסיק להו לשום עצים וכרבי אליעזר דתניא רבי אליעזר אומר (ויקרא ב, יב) לריח ניחוח אי אתה מעלה אבל אתה מעלה לשום עצים","אמר ליה רב אחא בריה דרבא לרב אשי ודלמא דכולי עלמא מותר לערב חובה בנדבה והכא בדרבי אליעזר קא מיפלגי דרבנן אית להו דרבי אליעזר ורבי לית ליה דרבי אליעזר","אמר ליה אי סלקא דעתך לרבי מותר לערב חובה בנדבה ודרבי אליעזר לית ליה אפשר דמייתי שיתין בחד מנא וחד בחד מנא ומגע להו וקמיץ","רבא אמר דכולי עלמא מותר לערב חובה בנדבה ודכולי עלמא אית להו דרבי אליעזר והכא בפלוגתא דרבי אליעזר בן יעקב ורבנן קא מיפלגי","דתנן אפילו מנחה של שישים עשרון נותן לה שישים לוג רבי אליעזר בן יעקב אומר אפילו מנחה של ששים עשרון אין לה אלא לוגה שנאמר (ויקרא יד, כא) למנחה ולוג שמן","רבנן סברי [כרבנן] דאמרי שישים לוג וכל חד וחד עשרון לוגה קא שקיל","ורבי סבר כר' אליעזר בן יעקב דאמר אין לה אלא לוגה ולא ידעינן אי חדא מנחה היא דסגי לה בחד לוג אי שתי מנחות נינהו דבעינן שני לוגין","רב אשי אמר בקטן והביא גדול קמיפלגי רבנן סברי קטן והביא גדול יצא ורבי סבר לא יצא","והא איפלגו בה חדא זמנא דתנן קטן והביא גדול יצא רבי אומר לא יצא","צריכא דאי איתמר בהא בהא קא אמרי רבנן משום דאידי ואידי קומץ הוא אבל התם דקא נפישי אימורין אימא מודו ליה לרבי","ואי איתמר בההיא בההיא קאמר רבי אבל בהא אימא מודי להו לרבנן צריכא","(סימן עצי\"ם זה\"ב יי\"ן עול\"ה תוד\"ה שו\"ר):","\u0001מתני׳\u0002 הרי עלי עצים לא יפחות משני גזירין לבונה לא יפחות מקומץ","חמשה קמצים הם האומר עלי לבונה לא יפחות מקומץ המנדב מנחה יביא עמה קומץ לבונה המעלה את הקומץ בחוץ חייב שני בזיכין טעונין שני קמצים","הרי עלי זהב לא יפחות מדינר זהב כסף לא יפחות מדינר כסף נחשת לא יפחות ממעה כסף פירשתי ואיני יודע מה פירשתי יהא מביא עד שיאמר לא לכך נתכוונתי:","\u0001גמ׳\u0002 תנו רבנן (ויקרא ב, א) קרבן מלמד שמתנדבין עצים וכמה שני גזירין וכן הוא אומר (נחמיה י, לה) והגורלות הפלנו על קרבן העצים רבי אומר עצים קרבן הם טעונין מלח וטעונין הגשה","אמר רבא ולדברי רבי עצים טעונין קמיצה אמר רב פפא לדברי רבי עצים צריכין עצים:","לבונה לא יפחות מן הקומץ: מנלן דכתיב (ויקרא ו, ח) והרים ממנו בקומצו מסלת המנחה ומשמנה ואת כל הלבונה מקיש לבונה להרמה דמנחה מה הרמה דמנחה קומץ אף לבונה נמי קומץ:","תנו רבנן הרי עלי למזבח יביא לבונה שאין לך דבר שקרב לגבי מזבח אלא לבונה פירשתי ואיני יודע מה פירשתי יביא מכל דבר שקרב למזבח","ותו ליכא והא איכא עולה איכא עורה לכהנים","והא איכא עולת העוף איכא"],[[0,"דלמא כולה חובה היא","ומכי שקיל קומץ קמא הוה ליה כל מה שבכלים שיריים וכי קמיץ דנדבה ומקטר לה הוו להו [כמקטיר] שיריים (שחסרו):"],[1,"דמסיק להו לשם עצים","לעולם דחובה מקטיר ברישא ודקאמר דילמא אינו שיריים נינהו וקמו להו בבל תקטירו דמקטר ליה לקומץ דנדבה לשם עצים:"],[1,"ואל המזבח לא יעלו","בתריה דההוא קרא דבל תקטירו כתיב:"],[2,"אית להו דר' אליעזר","הלכך כי מקטר לקומץ דנדבה מתנה ואומר אם איכא נדבה בההוא כלי תהוי הקטרה מעליא ואי כולה לחובה היא הקטרה קמייתא תהא הקטרה והך לשם עצים:"],[2,"ורבי לית ליה דר' אליעזר","הילכך לא מצי לאיתויי בחד מנא דתו לא מקטר לקומץ קמא דלמא כוליה חובה וקם ליה בבל תקטירו:"],[3,"אפשר דמייתי ששים בחד מנא וחד בחד מנא","וקמיץ מגדול ברישא ומתנה אי כולה חובה שפיר ואי לא הא דקמיצנא ליהוי מחובה ומאי דקמיצנא מכלי א' ליהוי אההוא עשרון ולאותה נדבה דפש בכלי אחר ומגע מגען לראש הכלים זה בצד זה כדי שיגעו ראשי הקלתות זו לזו כי היכי דלישתרי נדבה דבכלי גדול הקומץ דבכלי קטן ומקטיר חובה והדר דנדר דאי נמי הויא קמייתא כל כלי גדול חובה לא הוו להו שיריים שחסרו דמהנהו שיתין דבחד מנא לא שקיל ולא מידי מכי שקיל קומץ קמא:"],[5,"ששים לוג לששים עשרון","שבאותו כלי ומתנה כמה שנדרתי תהא לחובתי והשאר תהא נדבה וכל חד עשרון לוג שקיל ודחובה לחובה ונדבה לנדבה:"],[5,"אין לה (מנחה) אלא לוגה","לוג לכל המנחות ואי עריב שתים מנחות זו של שלשים וזו של שלשים בכלי אחד בעי להו ב' לוגין ואי חדא היא בעי חד לוג:"],[8,"קטן והביא גדול","וזה אי נמי לא נדר אלא שלשה עשרונות ומייתי חמשה לנדרו יצא ולא בעי אתנויי מידי:"],[9,"קטן והביא גדול","שור קטן עלי והביא גדול:"],[10,"אידי ואידי","בין מנחה גדולה ובין מנחה קטנה חד קומץ מקריב:"],[10,"אימורין דגדול נפישי מדקטן","ואיכא למימר לא הכי נדר בההוא קאמר לא יצא דנפישי אימורין דידיה:"],[13,"מתני' שני גזירין","שני בקעיות גדולות:"],[14,"והמעלה את הקומץ בחוץ חייב","כרת דהעלאה היא ובהאי כללא הוי מעלה קומץ בפנים דהקטרה מעלייתא היא הלכך לא חשיב להו בשיתא:"],[14,"שני בזיכין","של לחם הפנים:"],[15,"נחשת לא יפחות ממעה כסף","לא יפחות משוה מעה כסף דמייתי [נחושת] שוה מעה כסף:"],[15,"פירשתי","כך וכך זהב ואיני יודע כמה פירשתי:"],[15,"יביא","כל כך עד שיודע בעצמו שלעולם לא לכך נתכווין:"],[16,"גמ' קרבן","נפש כי תקריב קרבן מנחה (ויקרא ב׳:א׳):"],[16,"וכן הוא אומר","דעצים איקרו קרבן:"],[16,"וטעונין הגשה","בקרן דרומית מערבית כמנחה:"],[17,"עצים טעונים קמיצה","שמרסקן לעצים דקין עד שנוטל מהם מלא קומצו:"],[17,"עצים","שהתנדב אדם טעונים עצים להסיקן בעצי הקדש כשאר קרבנות:"],[18,"מנלן","דסתם הקטרה הוי קומץ:"],[19,"פירשתי","אחד מאותן הקריבין כולם למזבח ואיני יודע איזה מהם פירשתי וקא סלקא דעתך דודאי מדנחית למניינא דעתיה [נמי] אמידי דלית ביה היתר שיריים לכהנים ואע\"ג דאינו נקטר כולו כמין עולת העוף ומנחת נסכים והילכך יביא מכולן אבל היכא דאמר הרי עלי למזבח סתם משמע דבר שנקטר היינו לבונה:"],[20,"ותו ליכא","ואמילתא קמייתא קאי דאין לך דבר הקרב כולו למזבח אלא לבונה:"]],[[3,"","אפשר דמייתי שיתין בחד מנא ומגע להו וקמיץ. תימה והא תניא בהקומץ רבה (לעיל מנחות כד.) והרים ממנו בקומצו מן המחובר שלא יביא עשרון בשני כלים ויקמוץ ומשמע התם כגון דחק קפיזא בקבא אע\"ג דעריב מעילאי ואין לחלק בין עשרון אחד לכמה עשרונות דהא על כרחיך הא דקאמרי' הכא ומגע להו וקמיץ למה לי דמגע להו אי לאו משום דכתיב ממנו כדדריש להו התם וכיון דמדכתיב ממנו נפקא יש לנו למעט שני עשרונות בשני כלים כיון דחדא מנחה נינהו וחד קומץ לתרוייהו אע\"ג דנגעי כמו עשרון אחד בשני כלים וצריך לפרש שני כלים דהכא כעריבה של תרנגולים דהתם ואע\"ג דמפסקן מחיצתה הא נוגע וא\"ת דבכולה שמעתא משמע דלא אסרינן אלא לערב חובה בנדבה אבל חובה בחובה משמע דשרי וא\"כ לרבי יאמר אם ששים עשרונים נדרתי הרי עלי עדיין עשרון א' ואם פחות מס' נדרתי הרי עלי עדיין כל מה שחיסרתי מס' ועוד עשרון אחד יותר ומייתי שיתין בחד מנא וחד בחד מנא ומגע להו וקמיץ מהאי וקמיץ מהאי דכיון שהכל חובה יכול לערב ויש לומר כדשנינן לעיל בפרק התודה (מנחות דף פא.) התורה אמרה טוב אשר לא תדור ואת אמרת ליקו ולינדר לכתחילה ואין לנו לעשות כאן תקנה ע\"י הרי עלי אבל בהרי זו שרי דהוי נדבה ורבי כר' אליעזר בן יעקב ואין לומר דלייתי שיתין בחד מנא וחד בחד מנא ומגע להו וקמיץ להו מעשרון אנדבה דבששים דהא כי כלל חובה מערב' בנדבה הוה ליה חיסר שמנה וריבה שמנה:"],[13,"","לא יפחות משני גזירין. ודווקא כי אמר עצים אבל כי אמר עץ מייתי גזיר אחד כדאיתא בשקלים (דף יא):"],[13,"","לא יפחות מן הקומץ. במסכת שקלים בפרק שלשה עשר שופרות (דף יא) פליגי אי לשיעור יד בעלים אי לשיעור יד כהן:"],[14,"","המעלה את הקומץ בחוץ חייב. ובהא כללא הוי מעלה קומץ בפנים דהקטרה מעלייתא היא והלכך לא חשיב להו בשיתא כך פירש בקונטרס וא\"ת ומי סתם לן תנא כר' אליעזר דבפרק בתרא דזבחים (דף קי.) ומייתי ליה לעיל בסוף פרק קמא (מנחות דף יב:) דרבנן מחייבי בכזית בחוץ וי\"ל דקומץ דנקט לאו לאפוקי כזית אלא לאפוקי מאידך דרבי אליעזר דאמר בשני בזיכי לבונה עד שיקריב שני קמצים ולפירוש זה לא מיירי בקומץ דסולת:"],[20,"","והא איכא עולה וא\"ת והא איכא שמן למ\"ד בפרק כל התדיר (זבחים צא:) דכליל וי\"ל כיון דאיכא שמן דאכלי כהנים לא פסיקא ליה ועוד קשיא והא איכא עצים דאפי' לרבי דאמר טעון קמיצה הכל קרב כמפורש בהקומץ רבה (לעיל מנחות כ:):"]]],[["מוראה ונוצה","והאיכא נסכים לשיתין אזלי","והאיכא מנחת נסכים כיון דאיכא מנחה דאכלי כהנים מינה לא פסיקא ליה:","הרי עלי זהב לא יפחות מדינר זהב: ודלמא נסכא אמר ר' אלעזר דאמר מטבע ודלמא פריטי אמר רב פפא פריטי דדהבא לא עבדי אינשי:","כסף לא יפחות מדינר: ודלמא נסכא אמר ר' אלעזר דאמר מטבע ודלמא פריטי אמר רב ששת באתרא דלא סגו פריטי דכספא:","נחושת לא יפחות ממעה כסף: תניא רבי אליעזר בן יעקב אומר לא יפחות מצינורא קטנה של נחשת למאי חזיא אמר אביי שמחטטין בה פתילות ומקנחין בה נרות:","ברזל תניא אחרים אומרים לא יפחות מכליה עורב וכמה אמר רב יוסף אמה על אמה","איכא דאמרי לא יפחות מאמה על אמה למאי חזיא אמר רב יוסף לכליה עורב:","\u0001מתני׳\u0002 הרי עלי יין לא יפחות משלשה לוגין שמן לא יפחות מלוג רבי אומר שלשה לוגין","פירשתי ואיני יודע מה פירשתי יביא כיום מרובה:","\u0001גמ׳\u0002 תנו רבנן (במדבר טו, יג) אזרח מלמד שמתנדבין יין וכמה שלשה לוגין","ומנין שאם רצה להוסיף יוסיף תלמוד לומר יהיה יכול יפחות תלמוד לומר ככה:","שמן לא יפחות מן הלוג רבי אומר שלשה לוגין: במאי קא מיפלגי","אמרוה רבנן קמיה דרב פפא בדון מינה ומינה בדון מינה ואוקים באתרה קא מיפלגי","רבנן סברי דון מינה ומינה מה מנחה מתנדבין אף שמן נמי מתנדבין ומינה מה מנחה בלוג אף שמן בלוג","ורבי סבר דון מינה ואוקי באתרה מה מנחה מתנדבין אף שמן נמי מתנדבין ואוקי באתרה כנסכים מה נסכים שלשת לוגין אף שמן נמי שלשת לוגין","אמר להו רב פפא אי ממנחה גמר לה רבי דכולי עלמא לא פליגי דון מינה ומינה אלא רבי מאזרח גמיר לה","אמר ליה רב הונא בריה דרב נתן לרב פפא ומי מצית אמרת הכי והתניא קרבן מלמד שמתנדבין שמן וכמה שלשת לוגין מאן שמעת ליה דאמר שלשת לוגין רבי וקא מייתי לה מקרבן אמר ליה אי תניא תניא:","פירשתי ואיני יודע מה פירשתי יביא כיום מרובה: תנא כיום טוב הראשון של חג שחל להיות בשבת:","\u0001מתני׳\u0002 הרי עלי עולה יביא כבש ר' אלעזר בן עזריה אומר או תור או בן יונה","פירשתי מן הבקר ואיני יודע מה פירשתי יביא פר ועגל מן הבהמה ואיני יודע מה פירשתי יביא פר ועגל איל שעיר גדי וטלה פירשתי ואיני יודע מה פירשתי"],[[0,"מוראה ונוצה","נזרקין אצל מזבח (הפנימי) ונבלעין במקומן כדאמרי' במס' יומא בפ' קמא (דף כא.):"],[2,"לא פסיקא ליה","דלימא דבר הקרב כולו למזבח משום מנחת נסכים הואיל ואיכא מנחת נדבה דאינה כולה למזבח:"],[3,"נסכא","חתיכה אחת של זהב שקורין פלט\"א:"],[5,"מצינורא קטנה","מזלג קטן:"],[5,"מחטטין","מפילין ראש הפתילה כשהוא שרוף ובלע\"ז ממוקי\"ר:"],[5,"ומקנחין בה נרות","של מנורה מאפרה שבתוכה:"],[6,"כליה עורב","מסמרות חדין תוחבין בראש גג ההיכל לכלות העורבין שלא ישבו עליו:"],[8,"מתני' הרי עלי יין","לנסכים לא יפחות משלשה לוגין שהן פחותין שבנסכים:"],[8,"שמן לא יפחות מן הלוג","דחזי למנחת נדבה ואע\"ג דהוא מתכוין להקריבו בפני עצמו כנסכים והך סתמא כר' טרפון דאמר בפירקין דלעיל (מנחות דף קד.) אף מתנדבין שמן:"],[10,"גמ' אזרח","בפרשת נסכים כתיב (במדבר ט״ו:י״ג) כל האזרח יעשה ככה וגו' קרא יתירא הוא:"],[10,"שלשה לוגין","דבציר מהכי לא חזו:"],[11,"יהיה","התם כתיב ככם כגר כאזרח יהיה משמע יהיה לכם עוד נסכים אחריני:"],[14,"דון מינה","דשמן דבא נדבה גמרינן ממנחת נדבה כדאמר לקמן קרבן מלמד שמתנדבין שמן וההוא גבי מנחת נדבה כתיב (ויקרא ב׳:א׳) כי תקריב קרבן מנחה:"],[15,"ואוקי באתרה","בנסכים דשמן הבא בפני עצמו הוי כנסכים דומיא דיין:"],[16,"מאזרח גמר לה","כי היכי דגמרינן לעיל יין הכי נמי גמר רבי אזרח מלמד שמתנדבין שמן ודון מינה כל הנסכים שלשה לוגין:"],[17,"קרבן מנחה מלמד כו'","אלמא ממנחת נדבה גמר לה:"],[19,"מתני' יביא כבש","פחות שבעולות עולה ליכא לספוקי אלא בזכרים:"],[20,"פירשתי","אחד מקרבנות הבהמה ואיני יודע איזה מהם פירשתי:"],[20,"יביא","מכל מיני בהמה הזכרים גדולים דהיינו פר ועגל ואיל ושעיר גדי וטלה:"],[20,"פירשתי","את המין ואיני יודע אם מן הבהמה ואם מן העוף:"]],[[3,"","ודילמא נסכא. נראה דנסכא פחות מדינר דמטפי לא קשיא ליה דאזלינן בתר הפחות כדקאמר (לעיל מנחות דף קד:) הרי עלי עשרונות יביא שנים אבל טפי לא הרי עלי עולה יביא תור או בן יונה וכן כולם ובפ' בתרא דכתובות (דף קי:) ובבבא בתרא (דף קסה:) אמר כתוב בו כסף מגביהו דינר ופריך ואימא נסכא ובכל דוכתא קיי\"ל דיד בעל השטר על התחתונה ובמס' שקלים (דף יא) אמרינן הרי עלי זהב יביא דינר זהב אמר ר' אלעזר והוא שהזכיר צורה אבל לא הזכיר צורה מביא אפילו צינורא משמע דצינורא פחותה מדינר והיינו נסכא כדי לעשות צינורא וקשיא מהא דאמרי' בהגוזל בתרא (ב\"ק דף צו:) נסכא ועבדינהו זוזי משמע דזוזא פחות מנסכא וי\"ל דהתם בזוזי פשיטי דהוא שמיני שבצורי ואע\"ג דנקט זוזי סתם הכי נמי תנן בפ' אע\"פ (כתובות דף סה:) כלים של חמשים זוז ומפרש בגמ' חמשין זוזי פשיטי ובפרק הישן (סוכה דף כב:) אמר כזוזא מלעיל כאיסתירא מלתחת וקים לן איסתירא פלגא דזוזא אלא ההוא זוזא הוא זוזי פשיטי דארבע מנייהו קיימי באיסתירא באתרא דלא סגי פריטי דכספא הכא ובגט פשוט (ב\"ב קסה:) משני הכי ותימה דבפ' בתרא דכתובות (דף קי:) אמרי' פריטי דכספא לא עבדי אינשי ועוד קשיא דבגט פשוט (ב\"ב שם.) אמרי' מגביהו דינר ובכתובות (דף קי:) קתני מגביהו לוה כל מה שירצה וי\"ל דפריטי דהכא ובגט פשוט לאו דווקא והכי פריך ואימא פריטי כלומר פונדיונים או מעות איסרים כי התם בכתובות ומשני באתרא דלא סגי ובכתובו' פריך ואימא פרוטות ממש ואע\"ג דקתני מגביהו לוה כל מה שירצה לא משמע ליה שיוכל להגבותו פרוטות מדלא קתני מגביהו פרוטות שהוא הגרוע שבכל המטבעות:"],[5,"","שמוחטין בה את הפתילות לאו של מנורה דמלקחיים אית להן אלא [של] שאר נרות שהיו במקדש כדתנן בתמיד (דף ל) ובפ\"ק דסנהדרין (דף יד:) דאמרי' אפי' צינורא קטנה של הקדש צריכה עשרה בני אדם לפדותה לא כמו שפי' שם בקונטרס שטווין בה זהב אלא כי הכא שמוחטין בה את הפתילות אשכחן צינורא כדתנן (כלים פ\"ט מ\"ו) כוש שבלע את הצינורא:"],[6,"","כליה עורב. פירש בקונטרס מסמרות חדין תוחבין בראש גג ההיכל לכלות העורבים שלא ישבו עליו ובמקום אחר פירש כמין טבלא חדה זקופה על צידה וחדודה לחתוך כמו סכין ובערוך ערך כל פי' שעשו צורה להבריח בה העופות מגג ההיכל כדרך שעושין עכשיו שומרי זרעים וקראו אותה כליה עורב ועוד פירש בערוך מקדש ראשון ששכינה שרוייה בו לא היו צריכין כליה עורב שלא היו עופות פורחין עליו אבל במקדש שני שלא היתה קדושתו כקדושת ראשון הוצרכו לכליה עורב ובפ' שני דמועד קטן (דף ט.) לא משמע כן גבי בית שעשה שלמה דאכלו ביוה\"כ דקאמר איבעי לשיורי בבנין פורתא ומשני שיורי בנין לא משיירי איבעי ליה לשיורי באמת כליה עורב משמע שהיה שם כליה עורב ושמא תחלה עשה כליה עורב שלא היה יודע אחרי כן כשראה קדושתו שמטו:"],[17,"","אי תניא תניא. ולעולם כאן בדון מינה פליגי וה\"נ אית ליה לרב פפא בפ' כל התדיר (זבחים דף צא.) ובפ' כל שעה (פסחים דף לג.) והא דלא קאמר הכי בפ' כל המנחות באות מצה (מנחות סב:) דיחויא בעלמא הוא:"],[19,"","רבי אלעזר בן עזריה אומר יביא תור או בן יונה. בגמ' אמרי' דל\"פ דמר כי אתריה ואע\"פ שהיו רגילין לקנות קרבנות בירושלים כדאמרי' (ב\"מ כו.) מעות שנמצאו לפני סוחרי בהמה ואמרו (כריתות ח:) מעשה ועמדו קינים ברבעתיים מ\"מ דעת הנודר לפי מה שרואה בעיר:"],[20,"","פירשתי מן הבהמה כו'. ה\"ג יביא פר עגל ואיל שעיר גדי וטלה ויש ספרים דלא כתיב שעיר ועל כרחין גרסי' ליה כדקתני גבי שלמים שעירה:"]]],[["מוסיף עליהן תור ובן יונה","הרי עלי תודה ושלמים יביא כבש פירשתי מן בקר ואיני יודע מה פירשתי יביא פר ופרה עגל ועגלה מן הבהמה ואיני יודע מה פירשתי יביא פר ופרה עגל ועגלה איל ורחלה שעיר ושעירה גדי וגדייה טלה וטלייה","הרי עלי שור יביא הוא ונסכיו במנה עגל יביא הוא ונסכיו בחמש איל יביא הוא ונסכיו בשתים כבש יביא הוא ונסכיו בסלע","שור במנה יביא במנה חוץ מנסכיו עגל בחמש יביא בחמש חוץ מנסכיו איל בשתים יביא בשתים חוץ מנסכיו כבש בסלע יביא בסלע חוץ מנסכיו","שור במנה והביא שנים במנה לא יצא ואפילו זה במנה חסר דינר וזה במנה חסר דינר","שחור והביא לבן לבן והביא שחור גדול והביא קטן לא יצא קטן והביא גדול יצא רבי אומר לא יצא:","\u0001גמ׳\u0002 ולא פליגי מר כי אתריה ומר כי אתריה:","תנו רבנן הרי עלי עולה בסלע למזבח יביא כבש שאין לך דבר שקרב בסלע לגבי מזבח אלא כבש שקרב בסלע פירשתי ואיני יודע מה פירשתי יביא מכל דבר שקרב בסלע לגבי מזבח:","פירשתי מן הבקר ואיני יודע מה פירשתי יביא פר ועגל: אמאי וליתי פר ממה נפשך","הא מני רבי היא דאמר קטן והביא גדול לא יצא","אי רבי אימא סיפא שור במנה והביא שנים במנה לא יצא ואפילו זה במנה חסר דינר וזה במנה חסר דינר","שחור והביא לבן לבן והביא שחור גדול והביא קטן לא יצא קטן והביא גדול יצא רבי אומר לא יצא","רישא וסיפא רבי ומציעתא רבנן","אין רישא וסיפא רבי מציעתא רבנן והכי קאמר דבר זה מחלוקת רבי ורבנן:","תנן התם ששה לנדבה כנגד מי (סימן קמ\"ף ש\"ע)","אמר חזקיה כנגד ששה בתי אבות הכהנים שתקנו להם חכמים שיהא שלום זה עם זה","ר' יוחנן אמר מתוך שהנדבה מרובה תיקנו להם שופרות מרובין כדי שלא יתעפשו המעות","וזעירי אמר כנגד פר ועגל איל וכבש גדי ושעיר ורבי היא דאמר קטן והביא גדול לא יצא","ובר פדא אמר כנגד הפרים והאילים"],[[1,"תודה ושלמים","או זה או זה:"],[1,"יביא כבש","פחות שבתודה ושלמים:"],[1,"פירשתי כו'","תודה ושלמים איכא לספוקי בזכרים ונקבות:"],[1,"רחל","בת שתי שנים (טלה וטלייה) כבש בן שנתו:"],[2,"יביא הוא ונסכיו עמו במנה","כך נתפרש דינו בתורה שבע\"פ:"],[2,"בחמש","סלעים:"],[3,"אמר הרי עלי שור במנה יביאנו במנה חוץ מנסכיו","שהרי כך קבעו:"],[4,"שור במנה והביא שנים במנה לא יצא","שהרי קבע שור א' במנה:"],[6,"גמ' מר כי אתריה ומר כי אתריה","באתריה דת\"ק גריע כבש מעוף ובאתריה דרבי אליעזר גריע עוף מכבש:"],[7,"פירשתי","איזה קרבן אביא ואקננו בסלע מדנחת לפרושי איכא לספוקי נמי באחריני הלכך יביא מכל דבר הקרב למזבח שוה סלע מכל אחד ובלבד שיוכל לקנות דבר שלם מסלע:"],[8,"ממה נפשך","דאי נמי עגל נדר הא יש בכלל מרובה מועט:"],[13,"דבר זה","ששנינו יביא פר ועגל לאו דברי הכל היא אלא מחלוקת דרבי ורבנן דלגבי קטן והביא גדול [לרבי] לא יצא משום הכי נקט תנא פלוגתא בסיפא לפרושי רישא דלאו דברי הכל היא:"],[14,"תנן התם","במס' שקלים (דף ט:):"],[14,"ששה לנדבה","י\"ג שופרות היו במקדש שבעה מהן מפורשים מה נותנין בהם תיקלים חדתין ותיקלים עתיקין קינים וגוזלי עולה ועצים ולבונה וזהב לכפורת הרי שבעה וששה מהן לנדבה בהן היו נותנין המותרות ההולכות לנדבת צבור דהוא קיץ המזבח והוי הבשר לעולה ועורות לכהנים:"],[15,"","כנגד ששה בתי אבות שכל משמר חלוק לששה בתי אבות כנגד ששה ימי שבוע זה עובד יומו וזה עובד יומו ובשבת כולן שוין:"],[15,"כדי שיהא להן שלום זה עם זה","שעורות של בהמות הנקחות מן השופרות היו לכהנים שמקריבין העולות וכל זמן שאין המזבח בטל לא היו לוקחין מן השופרות ואם לא היה להם אלא שופר אחד אתו לאינצויי דשמא באותו יום של בית אב ראשון או של בית אב שני יביאו נדרים ונדבות הרבה לא יטול הבית אב מן השופר כלום ובשאר ימות השבוע של אלו בתי אבות לא מייתו נדרים ונדבות כ\"כ ונמצא אותן בתי אבות מקריבות מן השופר שלא יהא המזבח בטל והוו עורות שלהם ומנצי הנך קמאי בהדי הנך ואמרי יש לכם עורות ואנו אין לנו כלום ואי משום הנך עולות שהביאו יחידים במשמרות שלנו משום מזלינו הוא הלכך תקינו ששה שלא יטול זה משופרו של זה וכשהמעות באות נותנין אותן לששה שופרות:"],[17,"כנגד פר ועגל ואיל כבש וגדי ושעיר","שהמתנדב פר לעולה מביא ונותן לשופר ששמו פר במנה אחד כדאמר יביא במנה דפר (נקבה) במנה והמתנדב עגל מביא חמשה סלעים ונותן לשופר ששמו עגל וכן כולם והכהנים לוקחין ממעות שופר ששמו פר ויקריבו מאותו שופר פרים עד שיכלו כל המעות:"],[17,"דר' היא דאמר קטן והביא גדול לא יצא","ולהכי הוו ששה שאין עולה באה אלא מהנך ששה בהמות:"],[18,"כנגד פרים","של חטאת ציבור שאבדו והפריש אחרים תחתיהן ואח\"כ נמצאו הראשונים ונתקו לרעייה [דמיהן נופלין לשופר הראשון והאילים אשם גזילות ואשם מעילות שאבדו והפריש אחרים תחתיהן ואח\"כ נמצאו הראשונים ונתקו לרעייה דמיהן נופלין] לשופר השני ובאים לנדבת ציבור:"]],[[0,"","מוסיף עליהם תור ובן יונה. ולא גרסינן ובני יונה:"],[1,"","הרי עלי תודה או שלמים גרסי' ולא כספרים דגרסי תודה ושלמים:"],[2,"","כבש יביא הוא ונסכיו בסלע. תימה הא דאמר בפ' שני דכריתות (דף י:) גבי עולה ויורד מכאן אתה למד לעשירית האיפה בפרוטה דתניא הרי עלי בסלע למזבח יביא כבש דמדאמר רחמנא איל אשם בכסף שקלים דבן שתי שנים מכלל דבן שנה בסלע ומדחס רחמנא עליה דדלות למהוי חד משיתסר בעשירות דמטמא מקדש עשיר מביא כבש לחטאת בסלע ועני שני פרידים ברובע כדתנן (כריתות דף ח.) ועמדו קינין ברבעתיים פירוש רובע דינר שהוא אחד מט\"ז בסלע אלמא דכבש בלא נסכים הוי בסלע דחטאת אינה טעונה נסכים וי\"ל דכך ה\"ה דכבש בין יש עמו נסכים [בין אין עמו נסכים] בסלע כדקתני באיל הוא ונסכיו בשתים והיינו לפי שמצינו באיל האשם שהוא בכסף שקלים אע\"פ שאין נסכים באשם וא\"ת והא משמע בריש איזהו מקומן (זבחים מח.) דחטאת בת דנקא פירוש שתות דינר דהיינו מעה ובריש חגיגה (דף ו.) אמרי' דחגיגה מעה כסף ושה של פדיון פטר חמור אמרי' בפ\"ק דבכורות (דף יא.) בפטרוזא בת דנקא וי\"ל דודאי מה\"ת יכול להביא אפי' בפרוטה כדאמרינן בפ' [בתרא] דכריתות (דף כז.) שלא נתנה תורה קצבה במחוסרי כפרה שמא יוזלו טלאים ואין להן תקנה לאכול בקדשים ושמא עין יפה בסלע עין רעה בדנקא ואם יוזלו טלאים אפי' בפחות [מדנקא] אם הוא טוב ומובחר [מתכפר בהם] וא\"ת והא אמרינן בפ' הוציאו לו (יומא דף נה:) גבי לא היו שופרות לקיני חובה מפני התערובות שמא ימות א' מן הבעלים ופריך ונשקול ארבע זוזי מינייהו ונשדי בנהרא והנך לישתרו משמע שזהו שיעור דמי הקן ופי' שם בקונטרס ארבע זוזי מדינה והיינו חצי דינר צורי דאיסתירא דהוי סלע מדינה הוי פלגא זוזא כדאמר בפרק אע\"פ (כתובות דף סד.) וקשיא לההיא דכריתות דמשמע שהוא רובע דינר וי\"ל דהש\"ס נקט שיעור שהיו עומדים בימיהם ושמא אח\"כ נתייקרו אי נמי אורחיה דהש\"ס בכל דוכתא ד' זוזי ולאו דווקא כדאשכחן בפ' איזהו נשך (ב\"מ דף סט:) שקול ארבע זוזי ואימא ליה לפלניא דלוזפן זוזי ובפ' קמא דגיטין (דף יג.) דאי בעי שקיל ארבע זוזי מישראל ופסיל ליה ובפ' המקדיש שדהו (ערכין דף כט.) שקיל ארבע זוזי ושדי בנהרא ובפ' בתרא דר\"ה (דף לא:) גבי גר שנתגייר מפריש רובע לקינו פי' רש\"י רובע סלע ולא יתכן אלא רובע דינר כדפרישית כדמוכח בפ\"ק דכריתות (דף י:) דחד משיתסר הוי ועוד קשיא דבפ' הזהב (ב\"מ דף נב.) אשכחן רובע סתם דהוא רובע שקל דהיינו חצי דינר צורי גבי עד כמה תחסר ויהא רשאי לקיימה בסלע עד שקל בדינר עד רובע ומפרש התם רובע שקל וי\"ל דאדרבה משם ראיה דסתם רובע לאו רובע שקל מדהוה בעי למימר מעיקרא רובע דינר ומסיק רובע שקל ודייק לה מדקתני עד רובע ולא קתני עד רביע ועוד דומיא דסלע:"],[5,"","שחור והביא לבן. חלוקים קצת כדאמר פ\"ה דנזיר (דף לא:) ופ\"ק (דף ג) אוכמא למשכיה סומקא לבישריה חיורא לרידיא:"],[15,"","שיהא שלום זה עם זה. ואע\"פ שבערב השבת מחלקין העורות משום בעלי זרוע [כדאמרי'] בפרק מקום שנהגו (פסחים דף נז.) כאן יש תקנה לבעלי זרוע אע\"פ שכל בית אב נוטל מספר שלו הואיל וכל המשמרה ביחד:"],[17,"","ורבי היא דאמר קטן והביא גדול לא יצא. דלרבנן לא חיישינן אע\"ג דזמנין דשני ליה דההוא נתנן לשם אילים והוא מביא פר תחתיהם:"]]],[["והכבשים והשעירים והמותרות והמעה","כולהו כחזקיה לא אמרי לאנצויי לא חיישינן דכל חד וחד יומיה קא עביד","כר' יוחנן לא אמרי לאיעפושי לא חיישינן","כזעירי לא אמרי כיחידאה לא מוקמי","כבר פדא נמי לא אמרי מותרות כולהו נמי מותרות","מעה נמי לשקלים אזלא דתניא להיכן קלבון זה הולך לשקלים דברי ר' מאיר ר' אליעזר אומר לנדבה","ושמואל אמר כנגד מותר חטאת ומותר אשם ומותר אשם נזיר ומותר אשם מצורע ומותר מנחת חוטא ומותר עשירית האיפה של כהן גדול","ור' אושעיא אמר כנגד מותר חטאת ומותר אשם ומותר אשם נזיר ומותר אשם מצורע ומותר קינין ומותר מנחת חוטא","ושמואל מאי טעמא לא אמר כרבי אושעיא קינין תנא ליה רישא","ור' אושעיא תני ולא תני קינין והתני רבי אושעיא ותני קינין חד לקינין וחד למותר קינין","ורבי אושעיא מאי טעמא לא אמר כשמואל סבר לה כמאן דאמר מותר של עשירית האיפה של כהן גדול ירקב דתניא מותר מנחת נדבה מותר מנחה ירקב","מאי קאמר אמר רב חסדא הכי קאמר מותר מנחת חוטא נדבה מותר עשירית האיפה של כהן גדול ירקב","רבה אמר אפי' מותר עשירית האיפה של כהן גדול נמי נדבה אלא מותר לחמי תודה ירקב","בפלוגתא מותר עשירית האיפה של כהן גדול רבי יוחנן אמר נדבה רבי אלעזר אמר ירקב","מיתיבי מותר שקלים חולין ומותר עשירית האיפה ומותר קיני זבין וקיני זבות וקיני יולדות וחטאות ואשמות מותריהן נדבה","מאי לאו מותר עשירית האיפה של כהן גדול","לא מותר מנחת חוטא","אמר רב נחמן בר רב יצחק מסתברא כמאן דאמר מותר עשירית האיפה של כהן גדול ירקב","דתניא (ויקרא ה, יא) לא ישים עליה שמן ולא יתן עליה לבונה כי חטאת היא אמר רבי יהודה היא קרויה חטאת ואין אחרת קרויה חטאת לימד על עשירית האיפה של כהן גדול שאינה קרויה חטאת וטעונה לבונה","ומדאינה קרויה חטאת מותרה ירקב:","\u0001מתני׳\u0002 שור זה עולה ונסתאב אם רצה יביא בדמיו שנים שני שוורים אלו עולה ונסתאבו רצה יביא בדמיהן אחד ורבי אוסר","איל זה עולה ונסתאב אם רצה יביא בדמיו כבש כבש זה עולה ונסתאב אם רצה יביא בדמיו איל ורבי אוסר:"],[[0,"והכבשים","אשם נזיר ואשם מצורע הבאים בני שנה שנאמר בהן כבש ינתקו לרעייה דמיהן לשופר השלישי ואהכי לא מערב מותריהן עם מותר גזילות ומעילות משום דלא דמו דאלו בני שנה ואלו בני שתי שנים אלו באין לכפר ואלו להכשיר:"],[0,"והשעירים","שעירי חטאת של ציבור של רגלים מכפרים על טומאת מקדש וקדשיו בשאין בה ידיעה כדאמרינן בשבועות (דף ב.) ולא מפי השמועה. ואין לנו בהמה ניתקת לרעייה אלא אלו דכבשה ושעירה הבאין לחטאת יחיד אין ניתקות לרעיה אלא מתות:"],[0,"והמותרות","כגון מי שמקריב אחד מכל אלו והפריש מעות לשם כך והוזלו בהמות וניתותרו המעות נותן לשופר החמישי:"],[0,"והמעה","קולבון שכל יחיד מביא מחצית השקל בהכרעה באדר ואם נתנו בין שניהם שקל שלם נותנין קולבון אחד מעה קטנה מפני הכרעה שעכשיו לא נתנו בין שניהם אלא הכרע אחד ואילו הביאום כמשפטן היו שם שתי הכרעות לפיכך נותנין קולבון:"],[1,"כל חד וחד יומיה עביד","ואם באו לו קרבנות הרבה שלא צריך לשופר אין לו ליטול כלום בעורות שנקנו מן המעות שניתנו בשופר:"],[3,"כיחידאה לא מוקמינן","דלא חיישינן להא דרבי דאמר קטן והביא גדול לא יצא אלא המתנדב עגל נותן המעות לשופר של פר והכהנים מקריבין פרים מהם עד שיכלו כל המעות שיש שם:"],[4,"מותרות","בתמיה כלומר איהו חשיב חד שופר למותרות כולהו קמאי נמי דחשיב מן הניתקין לרעייה מותרות נינהו שניתותרו מכדי קרבן:"],[5,"לשקלים אזלו","לתרומת הלשכה עם שאר השקלים:"],[5,"לנדבה","לשופרות:"],[6,"","הכי גרסינן כנגד מותר חטאת מותר אשם נזיר ומותר אשם מצורע כו'. שהפריש מעות לאחד מכל אלו וניתותרו נותנן לשופרות ואשם סתם היינו אשם גזילות ומעילות לא מיעריב מותר דידיה בהדי חטאת ואשם נזיר ומצורע לא מיעריב בהדי אשם סתם דזה בין שתי שנים ואיל בן שנה ואשם מצורע לא מיערב בהדי אשם נזיר דאשם נזיר בא להכשירו לנזירות טהרה ואין נותנין מדמו לבהונות ואין טעונים נסכים ואשם מצורע נותנין מדמו לבהונות וטעון נסכים ובא להתירו במחנה:"],[6,"ומותר דמנחת חוטא","הואיל ואיקרי חטאת אזיל מותרה לנדבת צבור דהכי אמרינן במסכת תמורה (דף כג:) זה מדרש דרש יהוידע הכהן כל הבא ממותר חטאת וממותר אשם ילקח בהם עולות הבשר לשם ועורות לכהנים אבל מותר מעות שאר מנחות לא אזלי לנדבת צבור אלא הוא יוסיף משלו ומביא מנחה אחרת:"],[6,"ומותר עשירית האיפה","של כ\"ג שמקריב בכל יום ויום ואם הפריש מעות לעשירית האיפה של היום וניתותרו שוב אין יכול לצרפן לשם מחר אלא תפול לנדבת צבור שגם היא נקראת חטאת בפרק ואלו מגלחין במועד קטן (דף טז.) יקריב חטאתו זו עשירית האיפה של כהן גדול:"],[7,"ומותר קינין","המפריש מעות לקינו וניתותרו מקינין:"],[8,"תנא ליה רישא","בשבעה שופרות קמאי חשיב חד דשמיה קינין:"],[9,"","ור' אושעיא תני במתניתין שלש עשרה שופרות ולא תנא קינין בקמאי:"],[9,"חד לקינין","מחוסר כפרה מביא מעות לקינו ונותן בשופר ואוכל בקדשים לערב כדקיימא לן (עירובין דף לב.) אין ב\"ד של כהנים עומדים משם עד שיכלו כל המעות שבאותו שופר ולא חיישינן שמא לא יקריבו הואיל ואין באה על חטאת (ואי איהו גופיה לא מצי לאקרובינהו):"],[11,"מנחת חוטא","שהרי לשם חובה הפריש:"],[11,"נדבה","לשופרות:"],[12,"מותר לחמי תודה ירקב","דלאו חטאת איקרו ונדבת יחיד לא קרבי דבפני עצמו אי אפשר להקריבו שלא מצינו לחם קרב בפני עצמו ועם תודה אחרת אי אפשר להקריבו שהרי אין תודה קריבה בלא לחמה והכי מפרש בשקלים בפרק שני:"],[14,"מותר שקלים","הכניס מעות מרובים לשקלים ושקלן וניתותרו מהן:"],[18,"ואין אחרת","ואע\"פ שהיא חובה אינה קרויה חטאת שיהא לה דין חטאת שלא יהא טעון לבונה:"],[19,"","ומדלגבי לבונה לית ליה דין חטאת לגבי מותר נמי לית ליה דין חטאת ואע\"ג דאיקרי חטאת לאו דין חטאת אית לה דאימעטא לה מהאי קרא:"],[20,"מתני' אם רצה יביא בדמיו שנים","ואע\"ג דהוי גדול והביא קטן ובגמ' מפרש טעמא:"],[20,"ורבי אוסר","לכתחילה אבל אם הביא יצא דכיון דאמר זה אינו חייב באחריותו:"]],[[0,"","והמעה. קולבון שכל יחיד מביא מחצית השקל בהכרע באדר ואם נתנו בין שניהם שקל שלם נותנין קולבון א' מעה קטנה מפני הכרע שעכשיו לא נתנו שניהם אלא הכרע אחד ואילו הביאו כמשפטו היה שם שתי הכרעות לפיכך נותנין קולבון אחד כך פירש בקונט' וקשיא דאם הכרע עולה יותר ממעה היאך יוצאין בהכרע אחד במעה והלא חייבין שתי הכרעות ואם זה שיעור הכרע למה דחק בקונטרס לפרש כן לפיכך נראה דבכל הכרעות מיירי ופלוגתא היא בתוספ' דשקלים דתניא כמה הוא נותן קולבון מעה כסף אחד מכ\"ד כסף לסלע וחכמים אומרים חצי מעה של ארבע איסרות וקולבונות אלו מה היו עושין מהן נופלין לשקלים דברי ר\"מ ר' אלעזר אומר לנדבה:"],[8,"","ושמואל מאי טעמא לא אמר כרבי אושעיא. והוא הדין כל הני אמוראי דלעיל ורבי אושעיא מאי טעמא לא אמר כשמואל דבשלמא אמוראי דלעיל סברי דמותר מנחה לאו לנדבה אזלי אלא לרבי אושעיא דחשיב מותר מנחת חוטא כל שכן מותר עשירית האיפה:"],[18,"","היא קרויה חטאת. בפרק קמא (לעיל מנחות ד.) דרשינן לה ותרתי שמעת מינה:"],[19,"","ומדאינה קרויה חטאת ירקבו. לא דמי למותר מנחה דלא תירקב ואינה קרויה חטאת ועשירית האיפה דווקא דקרויה חטאת ביחזקאל (מו) אתא האי קרא לאפוקי דאין מותר קרויה חטאת ותירקב:"]]],[["\u0001גמ׳\u0002 והא אמרת רישא שור במנה והביא שנים במנה לא יצא","שור זה ונסתאב שאני:","שני שוורין אלו עולה ונסתאבו רצה יביא בדמיהן אחד ורבי אוסר: מאי טעמא","משום דהוה ליה גדול והביא קטן ואף על גב דנסתאב לכתחילה לא שרי רבי","ולפלוג נמי ברישא","רבי אכולה מילתא פליג ונטר להו לרבנן עד דמסקי מילתייהו והדר מיפליג עלייהו","תדע דקתני איל זה עולה ונסתאב רצה יביא בדמיו כבש כבש זה לעולה ונסתאב רצה יביא בדמיו איל ורבי אוסר שמע מינה:","איבעיא להו ממינא למינא מאי","תא שמע שור זה עולה ונסתאב לא יביא בדמיו איל אבל מביא בדמיו שני אילים ורבי אוסר לפי שאין בילה שמע מינה","אי הכי מאי איריא תרי אפילו חד נמי דהא בנסתאב לרבנן לא שני להו בין גדול לקטן","תרי תנאי ואליבא דרבנן:","רבי אוסר לפי שאין בילה: טעמא דאין בילה הא יש בילה שרי","והתנן איל זה עולה ונסתאב רצה יביא בדמיו כבש כבש זה עולה ונסתאב יביא בדמיו איל ורבי אוסר","תרי תנאי ואליבא דרבי","ובטהורים עגל והביא פר כבש והביא איל יצא סתמא כרבנן:","רצה יביא בדמיו ב' [כו']: אמר רב מנשיא בר זביד אמר רב לא שנו אלא דאמר שור זה עולה אבל אמר שור זה עלי עולה הוקבע","ודלמא עלי להביאו קאמר","אלא אי איתמר הכי איתמר אמר רב מנשיא בר זביד אמר רב לא שנו אלא דאמר שור זה עולה אי נמי אמר שור זה עלי עולה אבל אמר שור זה ודמיו עלי עולה הוקבע:","\u0001מתני׳\u0002 האומר אחד מכבשי הקדש ואחד משורי הקדש והיו לו שנים הגדול שבהן הקדש שלשה בינוני שבהם הקדש פירשתי ואיני יודע מה שפירשתי או שאמר לי אבא ואיני יודע מה הגדול שבהן הקדש:","\u0001גמ׳\u0002 אלמא מקדיש בעין יפה מקדיש אימא סיפא בינוני שבהן הקדש אלמא מקדיש בעין רעה מקדיש","אמר שמואל חוששין אף לבינוני דלגבי קטן עין יפה הוא","היכי עביד אמר רבי חייא בר רב ממתין לו עד שיומם ומחיל ליה לקדושתיה בגדול","אמר רב נחמן אמר רבה בר אבוה לא שנו אלא דאמר אחד משוורי הקדש אבל אמר שור בשוורי הקדש הגדול שבהן הקדש תורא בתוראי קאמר","איני והאמר רב הונא אמר ר' חייא משמיה דעולא האומר לחבירו בית בביתי אני מוכר לך מראהו עלייה לאו משום דגריע לא מעולה שבבתים:","מיתיבי שור בשוורי הקדש וכן שור של הקדש שנתערב באחרים הגדול שבהן הקדש וכולם ימכרו לצרכי עולות ודמיהן חולין","תרגומא אשור של הקדש שנתערב באחרים והא וכן קאמר תרגומא אגדול:","מיתיבי בית בביתי אני מוכר לך ונפל מראהו נפול עבד בעבדיי אני מוכר לך ומת מראהו מת"],[[0,"גמ' והא אמרת רישא","אפילו לרבנן:"],[0,"שור במנה כו'","ואמאי יביא בדמיו שנים:"],[1,"זה ונסתאב שאני","דכיון דאמר זה אקריב עולה ונסתאב אזל ליה נדריה דזה לא מצי למיקרב אבל התם דאמר הרי עלי שור במנה חייב עד שיביאנו:"],[3,"גדול והביא קטן","שבכל מקום שנים חשובים מאחד ואפילו שניהם שוין:"],[3,"ואף על גב דנסתאב","איכא למימר חלף ליה נדריה ובאחריות נמי לא ליחייב דהא אמר אלו אפילו הכי לכתחילה לא שרו:"],[4,"ליפלוג נמי ברישא","שור זה עולה ונסתאב יביא בדמיו שנים דהוי קטן והביא גדול נמי ליפלוג ולימא ורבי אוסר דלא שני ליה בין קטן והביא גדול לגדול והביא קטן:"],[6,"תדע","דארישא דנדר קטן והביא גדול נמי פליג:"],[6,"ורבי אוסר","אלמא בכבש אסר נמי רבי להביא בדמיו איל דהוי קטן והביא גדול דומיא דשור זה ונסתאב דלא יביא בדמיו שנים:"],[7,"ממינא למינא מאי","שור זה עולה ונסתאב מהו שיביא בדמיו שני אילים:"],[8,"לא יביא בדמיו איל","דקטן הוא יותר מדאי אבל יביא בדמיו שני אילים אלמא ממינא למינא שרי:"],[8,"לפי שאין בילה","שצריך להביא עמהם שתי מנחות בשני כלים ואין יכול לערבן בכלי אחד הלכך לא מיחזי כי ההוא דנדרו דנדר מידי דבאה מנחתו בכלי אחד וקא מייתי בשני כלים וקס\"ד דאי לאו משום המנחות לא איכפת לן אקרבנות אי נדר חד ומייתי תרין הואיל ומכח קמא אתו אבל מנחות דמביא מביתו בעינא דומיא דנדרו:"],[9,"אי הכי","דממינא למינא שרי מאי איריא כו':"],[10,"תרי תנאי","דאיכא דסבירא ליה דאפילו בנסתאב אסרי רבנן בגדול והביא קטן לכתחילה:"],[11,"הא יש בילה שרי","לאיתויי ממינא למינא:"],[12,"ורבי אוסר","אע\"ג דבכלי אחד אתיא מנחתו אפילו הכי לא מייתי מדמיו אלא דומיא דידיה:"],[13,"תרי תנאי כו'","דאיכא דקפיד אמנחות ואיכא דקפיד אקרבן גופיה:"],[14,"ובטהורים","סיפא דברייתא דשור זה עולה ונסתאב לא יביא בדמיו איל ובטהורים דלא נפל בהן מום:"],[15,"הוקבע","אחריותו עליו להביאו עולה אחת ולא לשתי עולות:"],[16,"ודלמא עלי להביא","לזה עולה קאמר וכיון דנסתאב אזל ליה נדריה שור זה לדמיו אם נסתאב הוקבע לעולה אחד דאי מייתי ב' עולות לא יצא אבל אי לא אמר עלי יצא כי היכי דעביד ליה דאינו חייב באחריותו:"],[18,"מתני' אחד מכבשי הקדש","למזבח:"],[18,"בינוני שבהן הקדש","מפרש בגמ':"],[18,"פירשתי","איזה מהן ולא ידעתי איזה:"],[18,"או שאמר לי אבא","בשעת מיתתו אחד משוורי הפרשתי להקדש:"],[18,"ואיני יודע","לאיזהו מהן:"],[18,"הגדול שבהן הקדש","דמסתמא מוטב שבהן הקדיש דכתיב מבחר נדריכם (דברים יב):"],[20,"גמ' חוששין אף לבינוני","דכיון דאמר אחד מהן הקדש לא ידענא אהי מינייהו חייל הקדש אי אגדול או אבינוני דהוי עין יפה לגבי קטן הלכך אתרווייהו חייל ומיהו לא קרב למזבח אלא חד מינייהו אבל היכא דאמר פירשתי ליכא לספוקי דודאי גדול פירש:"],[21,"היכי עביד","דמישתרי ליה חד מינייהו:"],[21,"ומחיל לקדושתיה בגדול","דממה נפשך אי אבינוני חל ולאו אגדול הרי זה נסתאב וחיללו בגדול ואי אגדול חל מעיקרא נמצא בינוני חולין מעיקרא:"],[22,"לא שנו","דחוששין אף לבינוני:"],[22,"תורא בתוראי","שור החשוב בשוורי:"],[23,"מראהו עלייה","שמראהו לעלייתו ואומר לו זו מכרתי לך קא סלקא דעתך עלייה ממש קאמר דגריעא דירתה משל בית אלמא בית בביתי לאו החשובה בביתי קאמר והוא הדין לתורא בתוראי:"],[24,"שור בשוורי הקדש","עולה:"],[24,"הגדול שבהן הקדש","עולה וכל האחרים ימכרו לצרכי עולות שמא אכל חד איכא למימר זה עולה:"],[24,"ודמיהן חולין","דקדש אינו תופס דמיו אלא בעל מום שיצא לחולין דנתפסין דמיו בקדושתו אבל האי דלא נפיק לחולין ולצורך קדשים נמכר אין דמיו קדושים ולהקדש נמי לא גזיל מידי דהא יהיב ליה הגדול שבהן קתני מיהא וכולן ימכרו כו' דחוששין לכולן אף על גב דאמר שור בשוורי וקשיא לרב נחמן:"],[25,"תרגומא","הא דקתני וכולן ימכרו לצרכי עולות:"],[25,"אשור של הקדש שנתערב באחרים","אבל אשור בשוורי ליכא לספוקי דגדול משמע:"],[25,"והא וכן קתני","דמשמע דין שניהם שוה:"],[25,"תרגומא","הא דקתני וכן אגדול דכן דינו שוה דנותן הגדול להקדש אבל לגבי ספיקא ליכא בשור בשוורי:"],[26,"ונפל","אחד מביתו מראהו ואומר זהו שמכרתי לך:"]],[[8,"","לפי שאין בילה. שצריך להביא שני מנחות עמהן בב' כלים ואין יכול לערבן יחד בכלי אחד הלכך לא מיחזי כי ההוא דנדרו ומן הדם לא חיישינן אם נתערב ולכל הפחות אם נתערב סולתן יכול לערב לכתחילה כדאמרן לעיל גבי יין:"]]],[["ואמאי ליחזי היידן נפל היידן מת","לוקח קא אמרת שאני לוקח דיד בעל השטר על התחתונה","השתא דאתית להכי אפילו תימא עלייה דגריעה יד בעל השטר על התחתונה:","\u0001מתני׳\u0002 הרי עלי עולה יקריבנה במקדש ואם הקריבה בבית חוניו לא יצא הרי עלי עולה שאקריבנה בבית חוניו יקריבנה במקדש ואם הקריבה בבית חוניו יצא רבי שמעון אומר אין זו עולה","הריני נזיר יגלח במקדש ואם גלח בבית חוניו לא יצא הריני נזיר שאגלח בבית חוניו יגלח במקדש ואם גלח בבית חוניו יצא ר' שמעון אומר אין זה נזיר:","\u0001גמ׳\u0002 יצא הא מקטל קטלה","אמר רב המנונא נעשה כאומר הרי עלי עולה על מנת שלא אתחייב באחריותה","אמר ליה רבא אלא מעתה סיפא דקתני הריני נזיר שאגלח בבית חוניו יגלח במקדש ואם גילח בבית חוניו יצא הכי נמי דנעשה כאומר הריני נזיר על מנת שלא אתחייב באחריות קרבנותיו נזיר כמה דלא מייתי קרבנותיו לא מתכשר","אלא אמר רבא אדם זה לדורון נתכוין אמר אי סגיא בבית חוניו טרחנא טפי לא מצינא לאיצטעורי","נזיר נמי האי גברא לצעורי נפשיה קא מיכוין אמר אי סגיא בבית חוניו טרחנא טפי לא מצינא לאיצטעורי","ורב המנונא אמר לך נזיר כדקאמרת עולה על מנת שלא אתחייב באחריותה קאמר","ואף רבי יוחנן סבר לה להא דרב המנונא דאמר רבה בר בר חנה אמר רבי יוחנן הרי עלי עולה שאקריבנה בבית חוניו והקריבה בארץ ישראל יצא וענוש כרת","תניא נמי הכי הרי עלי עולה שאקריבנה במדבר והקריבה בעבר הירדן יצא וענוש כרת:","\u0001מתני׳\u0002 הכהנים ששמשו בבית חוניו לא ישמשו במקדש שבירושלים ואין צריך לומר לדבר אחר שנאמר (מלכים ב כג, ט) אך לא יעלו כהני הבמות אל מזבח ה' בירושלים כי אם אכלו מצות (בקרב) אחיהם הרי אלו כבעלי מומין חולקין ואוכלין ולא מקריבין:","\u0001גמ׳\u0002 אמר רב יהודה כהן ששחט לעבודת כוכבים קרבנו ריח ניחוח","אמר רב יצחק בר אבדימי מאי קראה (יחזקאל מד, יב) יען אשר ישרתו אותם לפני גילוליהם והיו לבית ישראל למכשול עון על כן נשאתי ידי עליהם נאום ה' אלהים ונשאו עונם וכתיב בתריה ולא יגשו אלי לכהן לי אי עבד שירות אין שחיטה לאו שירות הוא:","איתמר שגג בזריקה רב נחמן אמר קרבנו ריח ניחוח רב ששת אמר אין קרבנו ריח ניחוח","אמר רב ששת מנא אמינא לה דכתיב והיו לבית ישראל למכשול עון [מאי] לאו או מכשול או עון ומכשול שוגג ועון מזיד","ורב נחמן מכשול דעון:","אמר רב נחמן מנא אמינא לה דתניא (במדבר טו, כח) וכפר הכהן על הנפש השוגגת בחטאה בשגגה מלמד שכהן מתכפר על ידי עצמו","במאי אילימא בשחיטה מאי איריא שוגג אפילו מזיד נמי אלא לאו בזריקה","ורב ששת אמר לך לעולם בשחיטה ובמזיד לא נעשה משרת לעבודת כוכבים","ואזדו לטעמייהו דאתמר הזיד בשחיטה רב נחמן אמר קרבנו ריח ניחוח ורב ששת אמר אין קרבנו ריח ניחוח","רב נחמן אמר קרבנו ריח ניחוח דלא עבד שירות רב ששת אמר אין קרבנו ריח ניחוח"],[[0,"ואמאי ניחזי הי נפיל","אי גדול נפל הפסיד לוקח דהא גדול שבבתים משמע ואי קטן נפל לית ליה פסידא:"],[1,"בעל השטר","כגון האי לוקח שבא בשטר מכירה ידו על התחתונה דהוי מוציא מחבירו עליו הראיה שהמוכר מוחזק בבתים הלכך ראיה על הלוקח אבל גבי הקדש גדול משמע:"],[3,"מתני' שאקריבנה בבית חוניו יקריבנה במקדש","דכיון דאמר הרי עלי עולה איחייב ליה בעולה:"],[3,"אם הקריבה בבית חוניו יצא","מפרש טעמא בגמ':"],[4,"יגלח במקדש","מביא קרבנותיו:"],[5,"גמ' והא מקטל קטלה","דשוחט חוץ הוא ואיהו איחייב בעולה מכי אמר הרי עלי עולה:"],[6,"אמר רב המנונא","כיון דאמר על מנת שאקריבנה בבית חוניו הוי כאילו אמר על מנת שאהרגנה ולא איתחייב באחריותה ומשום הכי יצא אבל חייב כרת משום שחוטי חוץ שהרי קרא עליה שם עולה:"],[7,"","נזיר לא מצי לאתנויי על מנת שלא אתחייב באחריות דקרבנותיו דכיון דחלה עליו נזירות לא פקעא מיניה עד דמייתי קרבנותיו:"],[8,"לדורון בעלמא קא מיכוין","ולא חל עליה שם עולה:"],[8,"טפי לא מצינא לאיצטעורי","ברחוק מארץ ישראל עומד וקרוב לחוניו ואליבא דרבא לא מחייב משום שחוטי חוץ:"],[10,"","ואמר ליה רב המנונא נזיר הוי ודאי טעמא כדקאמרת דלא חל עליה שם נזירות אבל עולה היינו טעמא נעשה כאומר וכו' ושם עולה עליה וחייב כרת:"],[11,"והקריבה בארץ ישראל","שלא בירושלים ולהכי נקט בא\"י דאף על גב דלא קיים נדרו יצא דקביעותא דבית חוניו לאו קביעות הוא (אלא היינו טעמא) דהוי כאומר על מנת שאהרגנה ועל מנת שלא אתחייב באחריותה דמה לי קטלה התם מה לי קטלה הכא וענוש כרת משום שחוטי חוץ אלמא שם עולה חל עלה כדרב המנונא:"],[12,"במדבר","קסבר משום משכן שהיה שם יהא עדיין המדבר קדוש:"],[12,"והקריבה בעבר הירדן","בארץ ישראל שלא בירושלים אפי' הכי יצא דעל מנת שלא אתחייב באחריות קאמר:"],[13,"מתני' ואין צריך לומר לדבר אחר","אם שמשו לעבודת כוכבים לא ישמשו עוד בירושלים:"],[13,"הרי אלו כבעלי מומין","שחולקין ואוכלין בקדשים כדאמר באלו מנחות (לעיל מנחות עג.) איש חולק ואפי' בעל מום:"],[14,"גמ' כהן ששחט בהמתו לעבודת כוכבים","לפני עבודת כוכבים ושב קרבנו שהוא מקריב במקדש אחרי כן ריח ניחוח הוא:"],[15,"אי עביד שירות","בעבודת כוכבים מיתסר במקדש ושחיטה לא איקרי שירות דהא במקדש כשרה בזר:"],[16,"שגג בזריקה","זרק דם לעבודת כוכבים בשוגג דהשתא עבד ליה שירות אלא ששוגג היה:"],[17,"מאי לאו או מכשול או עון","כלומר או שוגג או מזיד עשו שירות לעבודת כוכבים וכתיב לא יגשו אלי לכהן לי:"],[17,"עון מזיד","כדאמרי' במסכת יומא (דף לו:) עונות אלו הזדונות וכן הוא אומר הכרת תכרת עונה בה:"],[19,"בחטאה בשגגה","משמע אפי' נפש כהן בחטאה בשגגה יכול להקריב קרבנו ולהקריב על עצמו ובההיא פרשתא בעבודת כוכבים מישתעי כדכתיב (במדבר טו) וכי תשגו ולא תעשו וגו' זו עבודת כוכבים ששקולה כנגד כל התורה כולה:"],[20,"במאי","פלח לעבודת כוכבים דאיצטריך קרא לאכשורי לעבוד במקדש כי שגג:"]],[[2,"","אפילו תימא עלייה דגריעה יד בעל השטר על התחתונה. תימה דבפ' הנודר מן הירק (נדרים נו.) מסיק מאי עלייה מעולה שבנכסיו ושמא דיחויא הוא אבל קשיא דמסיק יד בעל השטר על העליונה ושמא לאפוקי יציע דווקא קאתי:"],[3,"","שאקריבנה בבית חוניו. אין שייך כאן תפוס לשון ראשון ואחרון דהוי כאומר עד בית חוניו מצינא דאטרח כדאיתא בגמ':"],[13,"","לא ישמשו במקדש בירושלים. בספר הזהיר כתוב כהן שהמיר דתו לא ישא את כפיו ולא יקרא ראשון דכתיב וקדשתו והוא אחליה לקדושתיה ועבדו ליה רבנן מעלה מפני דרכי שלום והאי כיון דאידחי אידחי כדתנן הכהנים ששמשו בבית חוניו לא ישמשו במקדש שבירושלים ורש\"י פירש דכשר וזה לשונו הרי אלו כבעלי מומין כו' מהכא נפקא לן דכהן שהמיר דתו וחזר בתשובה כשר לדוכן שהרי לא מצינו כהן בעל מום שיהא פסול לדוכן אלא אם היה לו מום בידיו כדאמרינן במגילה (דף כד:) מפני שהעם מסתכלין בו ותו הא דקתני לא ישמשו במקדש בירושלים ולהכי איצטריך בירושלים לאשמועינן דבנוב וגבעון היו מותרין לשמש כל שכן בזמן הזה שאין שירות ואין מקדש דודאי כשר לדוכן ולקרות בתורה תחילה ותו אמרינן (תענית דף כז.) אי מה משרת בעל מום לא אף מברך בעל מום לא ת\"ל לעמוד לשרת לעמידה הקשתיו ולא לדבר אחר עד כאן לשונו:"],[14,"","כהן ששחט לעבודת כוכבים קרבנו ריח ניחוח. ולרב ששת בשוגג ולרב נחמן אפי' במזיד:"]]],[["נעשה משרת לעבודת כוכבים","אמר רב נחמן מנא אמינא לה דתניא כהן שעבד עבודת כוכבים ושב קרבנו ריח ניחוח","במאי אילימא בשוגג מאי ושב שב ועומד הוא אלא פשיטא במזיד ואי בזריקה כי שב מאי הוי הא עבד לה שירות אלא לאו בשחיטה","ורב ששת אמר לך לעולם בשוגג והכי קאמר אם שב מעיקרו דכי עבד בשוגג עבד קרבנו ריח ניחוח ואם לאו אין קרבנו ריח ניחוח","השתחוה לעבודת כוכבים רב נחמן אמר קרבנו ריח ניחוח ורב ששת אמר אין קרבנו ריח ניחוח הודה לעבודת כוכבים רב נחמן אמר קרבנו ריח ניחוח ורב ששת אמר אין קרבנו ריח ניחוח","וצריכא דאי אשמעינן הך קמייתא בההיא קאמר רב ששת משום דעבד ליה שירות אבל שחיטה דלא עבד ליה שירות אימא מודה ליה לרב נחמן","ואי אשמעינן שחיטה משום דעבד ליה עבודה אבל השתחוה דלא עבד ליה עבודה אימא לא צריכא","ואי אשמעינן השתחואה משום דעביד ליה מעשה אבל הודה דדיבורא בעלמא אימא לא צריכא:","ואין צריך לומר דבר אחר [וכו']: מדקאמר אין צריך לומר דבר אחר מכלל דבית חוניו לאו עבודת כוכבים הוא","תניא כמאן דאמר בית חוניו לאו עבודת כוכבים הוא דתניא אותה שנה שמת שמעון הצדיק אמר להן שנה זו הוא מת אמרו לו מנין אתה יודע","אמר להן כל יום הכפורים נזדמן לי זקן אחד לבוש לבנים ונתעטף לבנים ונכנס עמי ויצא עמי שנה זו נזדמן לי זקן אחד לבוש שחורים ונתעטף שחורים ונכנס עמי ולא יצא עמי","לאחר הרגל חלה שבעת ימים ומת ונמנעו אחיו הכהנים מלברך בשם","בשעת פטירתו אמר להם חוניו בני ישמש תחתי נתקנא בו שמעי אחיו שהיה גדול ממנו שתי שנים ומחצה אמר לו בא ואלמדך סדר עבודה הלבישו באונקלי וחגרו בצילצול העמידו אצל המזבח אמר להם לאחיו הכהנים ראו מה נדר זה וקיים לאהובתו אותו היום שאשתמש בכהונה גדולה אלבוש באונקלי שליכי ואחגור בצילצול שליכי","בקשו אחיו הכהנים להרגו רץ מפניהם ורצו אחריו הלך לאלכסנדריא של מצרים ובנה שם מזבח והעלה עליו לשום עבודת כוכבים וכששמעו חכמים בדבר אמרו מה זה שלא ירד לה כך היורד לה על אחת כמה וכמה דברי רבי מאיר","אמר לו רבי יהודה לא כך היה מעשה אלא לא קיבל עליו חוניו שהיה שמעי אחיו גדול ממנו שתי שנים ומחצה ואף על פי כן נתקנא בו חוניו בשמעי אחיו אמר לו בא ואלמדך סדר עבודה והלבישו באונקלי וחגרו בצילצול והעמידו אצל המזבח אמר להם לאחיו הכהנים ראו מה נדר זה וקיים לאהובתו אותו היום שישתמש בכהונה גדולה אלבוש באונקלי שליכי ואחגור בצילצול שליכי","בקשו אחיו הכהנים להרגו סח להם כל המאורע בקשו להרוג את חוניו רץ מפניהם ורצו אחריו רץ לבית המלך ורצו אחריו כל הרואה אותו אומר זה הוא זה הוא הלך לאלכסנדריא של מצרים ובנה שם מזבח והעלה עליו לשם שמים שנאמר (ישעיהו יט, יט) (והיה) ביום ההוא יהיה מזבח לה' בתוך ארץ מצרים ומצבה אצל גבולה לה'","וכששמעו חכמים בדבר אמרו ומה זה שברח ממנה כך המבקש לירד לה על אחת כמה וכמה:","תניא אמר ר' יהושע בן פרחיה בתחלה כל האומר עלה לה אני כופתו ונותנו לפני הארי עתה כל האומר לי לירד ממנה אני מטיל עליו קומקום של חמין","שהרי שאול ברח ממנה וכשעלה בקש להרוג את דוד","אמר ליה מר קשישא בריה דרב חסדא לאביי ר' מאיר האי קרא דרבי יהודה מאי עביד ליה","לכדתניא לאחר מפלתו של סנחריב יצא חזקיה ומצא בני מלכים שהיו יושבין בקרונות של זהב הדירן שלא לעבוד עבודת כוכבים שנאמר (ישעיהו יט, יח) ביום ההוא יהיו חמש ערים בארץ מצרים מדברות שפת כנען"],[[0,"נעשה משרת","והא דאמרינן לעיל בשחיטה לא מיפסלא מוקי לה רב ששת בשוגג:"],[4,"הודה לעבודת כוכבים","אמר לה אלי אתה:"],[5,"קמייתא","שגג בזריקה:"],[5,"אבל שחיטה אימא מודה ליה לרב נחמן","ואפילו הזיד:"],[10,"נכנס עמי","לפני ולפנים:"],[12,"אמר ליה","שמעי לחוניו בא ואלמדך סדר עבודה:"],[12,"אונקלי","מלבוש של עור:"],[12,"צילצול","אזור:"],[12,"לאהובתו","לאשתו:"],[13,"זה שלא ירד לה","שמעי שלא ירד לה לגדולה כך נתקנא באחיו:"],[13,"היורד לה על אחת כמה וכמה","שאין מורידין אותו שלא יקלקל עצמו:"],[14,"בא ואלמדך","חוניו היה חכם משמעי:"],[16,"שברח ממנה","שלא רצה לקבלה מתחילה:"],[17,"","כל האומר עולה [או] מנחה בתחילה קודם שיפריש קרבנו ואמר עלי עולה או מנחה אני מטיל עליו כו' משום דאין טוב לומר עלי שמא לא יקיים וכתיב (דברים כ״ג:כ״ג) וכי תחדל לנדור לשון אחר בתחילה כל האומר עלה אני כופתו ומניחו לפני ארי ועכשיו כל האומר לירד הימנה אני מטיל עליו קומקום של חמין בתחילה הייתי שונא את הרבנות וכל האומר לי עלה לגדולה וכו' ועכשיו שעליתי לגדולה וכו' רבי יהושע בן פרחיה נשיא היה במסכת חגיגה (דף טז.):"],[20,"מדברות שפת כנען","שפת ישראל היושבים בארץ כנען וסיפא דקרא נשבעים בשם ה' צבאות:"]],[[10,"","נזדמן לי זקן אחד לבוש לבנים. בירושלמי פריך והכתיב וכל אדם לא יהיה באהל מועד ואפי' מלאכים דכתיב ודמות פניהם פני אדם ומשני דשמא שכינה היתה:"],[12,"","חוניו בני ישמש תחתי. תימה הא דרשינן בת\"כ תחת אביו בזמן שהוא ממלא מקום אביו וזה לא היה יודע סדר עבודה דהא קאמר ליה בא ואלמדך סדר [עבודה] ויש לומר דביראת חטא היה ממלא מקום אבותיו ואם תאמר וכי לא ראה כהן גדול משמש מעולם שהיה לובש באונקלי וחגור בצילצול ועוד הא אינו נעשה כהן גדול עד שיעשה סגן ויש לומר דלא היה יודע ובא ליכנס בכהונה גדולה תחילה:"],[15,"","והעלה עליו עולה לשם שמים. תימה הרי יש כאן איסור שחוטי חוץ ונראה דלבני נח היה מעלה (לעובדי כוכבים) הנודרים נדרים ונדבות:"],[17,"","בתחילה כל האומר עולה [או] מנחה. בתחלה קודם שיפריש קרבנו ואומר הרי עלי עולה ומנחה אני מטיל עליו כו' משום דאין טוב לומר עלי שמא לא יקיים וכתיב (דברים כ״ג:כ״ג) וכי תחדל לנדור וגו' כך פירש הקונטרס עוד פירש בקונט' פירוש אחר גרסינן בתחילה כל האומר עלה אני כופתו ומניחו לפני ארי עכשיו כל האומר לירד ממנה אני מטיל עליו קומקום של חמין בתחילה הייתי שונא הרבנות וכל האומר לי עלה לגדולה כו' ועכשיו שעליתי לגדולה רבי יהושע בן פרחיה נשיא היה במסכ' חגיגה (דף טז.) עד כאן לשונו ואותו לשון ראשון היה כתוב בספר ולעיל הוה ליה לאיתויי גבי הרי עלי עולה ורבינו קלונימוס אביו של רבי משולם הגיה כלשון שני בשעת פטירתו והסופר טעה בין עלה לעולה ושלשה דברים הגיה כמפי נבואה בשעת פטירתו זאת ועוד אחרת שהיה כתוב בספרים בפרק בית שמאי בזבחים (דף מה:) דברים שאין חייבין עליהם משום פיגול חייבין עליהם משום נותר וטמא חוץ מן הדם ונומי רבי שמעון מחייב בדבר שדרכו להיאכל פי' אמר רבי שמעון ועוד הגיה בשבועות (דף יב:) שהיה כתוב בספרים קרבנות ציבור סכין מושכתן למשהו ולא היו יודעין מהו ואמר דגרסינן למה שהן:"]]],[["ונשבעות לה' צבאות הלכו לאלכסנדריא של מצרים ובנו מזבח והעלו עליו לשם שמים שנאמר (ישעיהו יט, יט) ביום ההוא יהיה מזבח לה' בתוך ארץ מצרים","(ישעיהו יט, יח) עיר ההרס יאמר לאחת מאי עיר ההרס יאמר לאחת כדמתרגם רב יוסף קרתא דבית שמש דעתיד למיחרב איתאמר דהיא חדא מנהון וממאי דעיר ההרס לישנא דשימשא היא דכתיב (איוב ט, ז) האומר לחרס ולא יזרח","(ישעיהו מג, ו) הביאי בני מרחוק ובנותי מקצה הארץ הביאי בני מרחוק אמר רב הונא אלו גליות של בבל שדעתן מיושבת עליהן כבנים ובנותי מקצה הארץ אלו גליות של שאר ארצות שאין דעתן מיושבת עליהן כבנות","אמר רבי אבא בר רב יצחק אמר רב חסדא ואמרי לה אמר רב יהודה אמר רב מצור ועד קרטיגני מכירין את ישראל ואת אביהם שבשמים ומצור כלפי מערב ומקרטיגני כלפי מזרח אין מכירין את ישראל ולא את אביהן שבשמים","איתיביה רב שימי בר חייא לרב (מלאכי א, יא) ממזרח שמש ועד מבואו גדול שמי בגוים ובכל מקום מוקטר מוגש לשמי ומנחה טהורה אמר ליה שימי את דקרו ליה אלהא דאלהא","בכל מקום מוקטר מוגש לשמי בכל מקום סלקא דעתך אמר רבי שמואל בר נחמני אמר ר' יונתן אלו תלמידי חכמים העוסקים בתורה בכל מקום מעלה אני עליהן כאילו מקטירין ומגישין לשמי","ומנחה טהורה זה הלומד תורה בטהרה נושא אשה ואחר כך לומד תורה","(תהלים קלד, א) שיר המעלות הנה ברכו את ה' כל עבדי ה' העומדים בבית ה' בלילות מאי בלילות אמר ר' יוחנן אלו תלמידי חכמים העוסקים בתורה בלילה מעלה עליהן הכתוב כאילו עסוקים בעבודה","(דברי הימים ב ב, ג) לעולם זאת על ישראל אמר רב גידל אמר רב זה מזבח בנוי ומיכאל שר הגדול עומד ומקריב עליו קרבן","ורבי יוחנן אמר אלו תלמידי חכמים העסוקין בהלכות עבודה מעלה עליהם הכתוב כאילו נבנה מקדש בימיהם","אמר ריש לקיש מאי דכתיב (ויקרא ז, לז) זאת התורה לעולה למנחה ולחטאת ולאשם כל העוסק בתורה כאילו הקריב עולה מנחה חטאת ואשם","אמר רבא האי לעולה למנחה עולה ומנחה מיבעי ליה אלא אמר רבא כל העוסק בתורה אינו צריך לא עולה (ולא חטאת) ולא מנחה ולא אשם","אמר רבי יצחק מאי דכתיב (ויקרא ו, יח) זאת תורת החטאת וזאת תורת האשם כל העוסק בתורת חטאת כאילו הקריב חטאת וכל העוסק בתורת אשם כאילו הקריב אשם:","\u0001מתני׳\u0002 נאמר בעולת בהמה (ויקרא א, ט) אשה ריח ניחוח ובעולת עוף (ויקרא א, ט) אשה ריח ניחוח ובמנחה (ויקרא ב, ב) אשה ריח ניחוח לומר לך אחד המרבה ואחד הממעיט ובלבד שיכוין לבו לשמים:","\u0001גמ׳\u0002 אמר ר' זירא מאי קראה (קהלת ה, יא) מתוקה שנת העובד אם מעט ואם הרבה יאכל","רב אדא בר אהבה אמר מהכא (קהלת ה, י) ברבות הטובה רבו אוכליה ומה כשרון לבעליו:","תניא אמר רבי שמעון בן עזאי בוא וראה מה כתיב בפרשת קרבנות שלא נאמר בהן לא אל ולא אלהים אלא ה' שלא ליתן פתחון פה לבעל דין לחלוק","ונאמר בשור הגס (ויקרא א, ט) אשה ריח ניחוח ובעוף הדק (ויקרא א, ט) אשה ריח ניחוח ובמנחה (ויקרא ב, ב) אשה ריח ניחוח לומר לך אחד המרבה ואחד הממעיט ובלבד שיכוין את לבו לשמים","ושמא תאמר לאכילה הוא צריך תלמוד לאמר (תהלים נ, יב) אם ארעב לא אומר לך כי לי תבל ומלואה ונאמר (תהלים נ, י) כי לי כל חיתו יער בהמות בהררי אלף ידעתי כל עוף הרים וזיז שדי עמדי האוכל בשר אבירים ודם עתודים אשתה","לא אמרתי אליכם זבחו כדי שתאמר אעשה רצונו ויעשה רצוני לא לרצוני אתם זובחים אלא לרצונכם אתם זובחים שנאמר (ויקרא יט, ה) לרצונכם תזבחהו","דבר אחר לרצונכם תזבחהו לרצונכם זבחו לדעתכם זבחו","כדבעא מיניה שמואל מרב הונא מנין למתעסק בקדשים שהוא פסול שנאמר ושחט את בן הבקר שתהא שחיטה לשם בן בקר","אמר לו זו בידינו הוא לעכב מנין תלמוד לאמר לרצונכם תזבחהו לדעתכם זבחו:","\u0001הדרן עלך הרי עלי עשרון וסליקא לה מסכת מנחות\u0002"],[[2,"כבנים","דעת זכרים מיושבת עליהם יותר משל נקבות:"],[2,"","בני בבל אין להם עול מלכות כשאר גליות שבכל הארצות:"],[3,"מכירין את ישראל","בכבודן הראשון מכירין ואין מכבידין עולם:"],[3,"ואת אביהם שבשמים","שמאמצים בהקדוש ברוך הוא ואין מאמצים בעבודת כוכבים:"],[4,"שימי את","בתמיה אתה הוא שימי חכם גדול ומקשה לי דבר זה ויש אומרים רב לא היה זוקף עיניו אלא כובשן כל שעה משום צניעות:"],[6,"זה הלומד תורה בטהרה","עליו הוא אומר לשמי ומנחה טהורה:"],[8,"לעולם זאת על ישראל","מקרא הוא בדברי הימים (ב סי' ב) בשלמים ובקרבנות משתעי דלעולם הם עומדים והיכי דמי מזבח בנוי בשמים ומיכאל עומד ומקטיר עליו:"],[10,"מאי דכתיב זאת התורה","ולא כתיב בה חוקה:"],[11,"עולה ומנחה מיבעי ליה","דליהוי משמע זאת התורה היא עולה ומנחה כו':"],[11,"אין צריך לא עולה וכו'","דהכי משמע זאת התורה לעולה כלומר במקום העולה למנחה בשביל המנחה כגון לכם בשבילכם כלומר התלמוד תורה מכפר על עונותינו:"],[12,"בתורת חטאת","כגון סדר קדשים דמיירי בהלכות עבודה:"],[14,"שנת העובד","עבודת קרבנות ומביאו למזבח מתוקה שנתו שהוא ישן ולא ירא:"],[14,"אם מעט ואם הרבה יאכל","מתן שכרו:"],[15,"ברבות הטובה","קרבנות:"],[15,"רבו אוכליה","כהנים:"],[15,"ומה כשרון לבעליו","להקדוש ברוך הוא כי אם ראות עיניו שזה מתכוין לטובה:"],[16,"לבעל הדין","לאומרים רשויות הרבה הן והדבר מוכיח שזה ששמו כך ציום להקריב לו מנחה [וזה] ששמו כך ציום להקריב לו פרים וזה אילים לכך נאמר בכולם ריח ניחוח לה':"],[17,"אחד המרבה","להביא קרבנות:"],[19,"כדי שתאמר אעשה רצונו","להקריב לו קרבן ויעשה רצוני לפי שהוא צריך לכך ואשחדנו:"],[19,"לא לרצוני אתם זובחים","כלומר לא להנאותי שאיני רוצה להטריח אתכם לעשות על כרחכם:"],[19,"לרצונכם","לצורך עצמכם לקיים מצוותי שתהא כפרה לכם בכך:"],[20,"לרצונכם זבוחו","שתהא כוונתכם לשחוט פרט למתעסק בסכין לחתוך דבר אחר ושחט בהמת קדשים שפסולה:"],[21,"מנין למתעסק","בדבר אחר ושחט בהמת קדשים שהוא פסול:"],[22,"זו בידינו הוא","דמצוה לכוין דעתו:"],[22,"לרצונכם תזבחהו","שנה עליו הכתוב לעכב:"]],[[6,"","הלומד תורה בטהרה נושא אשה ואחר כך לומד תורה. בפרק קמא דקידושין (דף כט:) איכא למאן דאמר איפכא ואמרינן לא פליגי הא לן והא להו:"],[8,"","ומיכאל שר הגדול עומד ומקריב עליו קרבן. מדרשות חלוקין יש מי שאומר נשמותיהן של צדיקים ויש מי שאומר כבשים של אש והיינו דאמרינן בשמונה עשרה בעבודה ואשי ישראל ותפלתם מהרה באהבה תקבל ברצון ויש אומרים דקאי אדלעיל והשב את העבודה לדביר ביתך ואשי ישראל. לא מצאתי יותר:"]]]]};
